

/* ============================================================================
   SUPPLEMENTAL TRAITS — v2
   The original set clustered hard at intensity 2–3. That's the real reason the
   sliders felt "grouped": at high magnitudes the eligible pool collapsed to one
   or two traits, so every extreme setting returned the same handful of results.
   These fill the intensity 1 / 4 / 5 tails across every category so the
   continuous range system below actually has distinct material at every point
   on the dial.
   ids start at 90000 to avoid any collision with the original set.
   ========================================================================== */
const TRAITS_SUPPLEMENT = [

/* ---------- Verbosity Traits ---------- */
{id:90001,section:"Verbosity Traits",category:"High-Volume & Wordy",trait:"Slightly over-explains",desc:"Adds one more clause than strictly needed, and stops there.",example:"It's on the table — the small one, by the window.",intensity:1,rarity:"common",pol:{vol:1}},
{id:90002,section:"Verbosity Traits",category:"High-Volume & Wordy",trait:"Warms up after a while",desc:"Quiet at first, then noticeably chattier once comfortable.",example:"Sorry, I've been talking for ten minutes, haven't I.",intensity:1,rarity:"common",pol:{vol:1}},
{id:90003,section:"Verbosity Traits",category:"High-Volume & Wordy",trait:"One extra sentence",desc:"Reliably tacks a single unnecessary follow-up onto every answer.",example:"Yes. Not that it matters much either way.",intensity:1,rarity:"common",pol:{vol:1}},
{id:90004,section:"Verbosity Traits",category:"High-Volume & Wordy",trait:"Buries the point in preamble",desc:"Takes several minutes of context before arriving anywhere near the answer.",example:"To understand this properly you have to go back about four years—",intensity:4,rarity:"signature",pol:{vol:1}},
{id:90005,section:"Verbosity Traits",category:"High-Volume & Wordy",trait:"Talks through the silence",desc:"Fills every gap in a conversation rather than let one sit.",example:"—anyway, so, right, where were we, yes, so the thing is—",intensity:4,rarity:"uncommon",pol:{vol:1}},
{id:90006,section:"Verbosity Traits",category:"High-Volume & Wordy",trait:"Answers three questions you didn't ask",desc:"Each reply expands to cover adjacent topics nobody raised.",example:"You asked about Tuesday. I'll do the whole week, it's cleaner.",intensity:4,rarity:"signature",pol:{vol:1}},
{id:90007,section:"Verbosity Traits",category:"High-Volume & Wordy",trait:"Physically cannot stop",desc:"Speech runs until someone physically intervenes or they lose their voice.",example:"(has been talking since the food arrived; the plates are cold)",intensity:5,rarity:"signature",pol:{vol:1}},
{id:90008,section:"Verbosity Traits",category:"High-Volume & Wordy",trait:"Monologue as default state",desc:"Treats every exchange as an opportunity for an uninterrupted address.",example:"No, no — let me finish. I'm about a third of the way in.",intensity:5,rarity:"signature",pol:{vol:1}},
{id:90009,section:"Verbosity Traits",category:"High-Volume & Wordy",trait:"Exhausts the listener",desc:"Volume of speech is the primary thing people remember about them.",example:"(three people have quietly left; they have not noticed)",intensity:5,rarity:"signature",pol:{vol:1}},

{id:90010,section:"Verbosity Traits",category:"Minimal & Ultra-Brief",trait:"A shade terse",desc:"Marginally shorter than most people, nothing anyone comments on.",example:"If you like.",intensity:1,rarity:"common",pol:{vol:-1}},
{id:90011,section:"Verbosity Traits",category:"Minimal & Ultra-Brief",trait:"Skips the greeting",desc:"Starts at the content, drops the social preamble.",example:"The gate's open.",intensity:1,rarity:"common",pol:{vol:-1}},
{id:90012,section:"Verbosity Traits",category:"Minimal & Ultra-Brief",trait:"Answers without elaborating",desc:"Gives the answer and waits, offering nothing extra.",example:"Yes. (waits)",intensity:4,rarity:"uncommon",pol:{vol:-1}},
{id:90013,section:"Verbosity Traits",category:"Minimal & Ultra-Brief",trait:"Sentence-fragment only",desc:"Rarely completes a full grammatical sentence.",example:"North road. Two hours. Maybe three.",intensity:4,rarity:"signature",pol:{vol:-1}},
{id:90014,section:"Verbosity Traits",category:"Minimal & Ultra-Brief",trait:"Speaks perhaps ten words an hour",desc:"Verbal output is so low that any sentence becomes an event.",example:"(the room stops when they open their mouth)",intensity:5,rarity:"signature",pol:{vol:-1}},
{id:90015,section:"Verbosity Traits",category:"Minimal & Ultra-Brief",trait:"Communicates almost entirely without words",desc:"Runs their whole life on gesture, expression, and written notes.",example:"(slides the paper across; that's the conversation)",intensity:5,rarity:"signature",pol:{vol:-1}},

{id:90016,section:"Verbosity Traits",category:"Pacing & Situation-Driven",trait:"Barely shifts tempo",desc:"Speed changes only slightly with situation — you'd have to be listening.",example:"(a fraction quicker than usual; nobody notices)",intensity:1,rarity:"common",pol:{pace:1}},
{id:90017,section:"Verbosity Traits",category:"Pacing & Situation-Driven",trait:"Slows a touch when tired",desc:"A small, predictable drag on the words late in the day.",example:"...right. Right. Sorry, long one.",intensity:1,rarity:"common",pol:{pace:-1}},
{id:90018,section:"Verbosity Traits",category:"Pacing & Situation-Driven",trait:"Quickens near the truth",desc:"Speeds up sharply whenever the conversation approaches the real subject.",example:"—anyway-that's-not-important-what-I-meant-was—",intensity:4,rarity:"signature",pol:{pace:1}},
{id:90019,section:"Verbosity Traits",category:"Pacing & Situation-Driven",trait:"Two entirely different speakers",desc:"Public tempo and private tempo have nothing in common.",example:"(clipped and fast all day; unrecognizably slow at home)",intensity:5,rarity:"signature",pol:{pace:1}},
{id:90020,section:"Verbosity Traits",category:"Pacing & Situation-Driven",trait:"Tempo collapses entirely under threat",desc:"Speech either floods out or stops dead; nothing in between survives pressure.",example:"—everything-at-once— (then nothing, for a full minute)",intensity:5,rarity:"signature",pol:{pace:1}},

{id:90021,section:"Verbosity Traits",category:"Stylized & Elaborate",trait:"One borrowed flourish",desc:"Keeps one slightly theatrical phrase and uses it sparingly.",example:"As they say. (they do not say)",intensity:1,rarity:"common",pol:{form:1}},
{id:90022,section:"Verbosity Traits",category:"Stylized & Elaborate",trait:"Occasionally rhetorical",desc:"Reaches for a shaped sentence once in a conversation, no more.",example:"We came, we complained, we left.",intensity:1,rarity:"common",pol:{form:1}},
{id:90023,section:"Verbosity Traits",category:"Stylized & Elaborate",trait:"Speaks in constructed set-pieces",desc:"Most statements arrive pre-shaped, as though drafted beforehand.",example:"There are three things worth saying here, and I'll take them in order.",intensity:4,rarity:"signature",pol:{form:1}},
{id:90024,section:"Verbosity Traits",category:"Stylized & Elaborate",trait:"Everything is a performance",desc:"No utterance, however trivial, is delivered plainly.",example:"(announces that the bread is ready as though declaring war)",intensity:5,rarity:"signature",pol:{form:1}},
{id:90025,section:"Verbosity Traits",category:"Stylized & Elaborate",trait:"Incomprehensibly ornate",desc:"Style has entirely overtaken meaning; listeners often can't extract the point.",example:"The vessel of the hour tips its amber freight upon us, and we drink, and are drowned.",intensity:5,rarity:"signature",pol:{form:1}},

{id:90026,section:"Verbosity Traits",category:"Repetitive & Circular",trait:"Returns to one point twice",desc:"Comes back to a favourite idea a second time, then moves on.",example:"Like I said — the timing. That's the whole thing.",intensity:3,rarity:"uncommon",pol:{}},
{id:90027,section:"Verbosity Traits",category:"Repetitive & Circular",trait:"Circles the same complaint",desc:"Every conversation eventually returns to one standing grievance.",example:"And another thing about the drainage—",intensity:4,rarity:"signature",pol:{}},
{id:90028,section:"Verbosity Traits",category:"Repetitive & Circular",trait:"Locked in a single loop",desc:"Says the same three things in rotation regardless of what's asked.",example:"They took it. They shouldn't have taken it. It was mine. They took it.",intensity:5,rarity:"signature",pol:{}},

/* ---------- Vocabulary Traits ---------- */
{id:90030,section:"Vocabulary Traits",category:"Abstractness & Sensory Modality",trait:"One concrete anchor",desc:"Mostly abstract, but always names one physical thing per point.",example:"It's a mess. Like the barn, that winter.",intensity:1,rarity:"common",pol:{}},
{id:90031,section:"Vocabulary Traits",category:"Abstractness & Sensory Modality",trait:"Faintly tactile",desc:"Slight preference for touch words over any other sense.",example:"Rough week. Rough all the way through.",intensity:1,rarity:"common",pol:{}},
{id:90032,section:"Vocabulary Traits",category:"Abstractness & Sensory Modality",trait:"Thinks in weather",desc:"Frames moods, people, and events consistently as conditions of sky and season.",example:"He came in like low pressure. Everyone felt it before he spoke.",intensity:4,rarity:"signature",pol:{}},
{id:90033,section:"Vocabulary Traits",category:"Abstractness & Sensory Modality",trait:"Everything has a smell",desc:"Reaches for olfactory description far past where it's useful.",example:"The whole arrangement smelled wrong. Not a figure of speech.",intensity:4,rarity:"signature",pol:{}},
{id:90034,section:"Vocabulary Traits",category:"Abstractness & Sensory Modality",trait:"Cannot speak abstractly at all",desc:"Every concept must be converted to a physical object before they can discuss it.",example:"Don't say 'justice'. Show me the man and the rope and I'll tell you.",intensity:5,rarity:"signature",pol:{}},
{id:90035,section:"Vocabulary Traits",category:"Abstractness & Sensory Modality",trait:"Synaesthetic overflow",desc:"Senses bleed into each other in every description, constantly.",example:"That note was orange. Cold orange. You heard it too.",intensity:5,rarity:"signature",pol:{}},

{id:90036,section:"Vocabulary Traits",category:"Affective & Emotional Intensity",trait:"Words run hotter than the room",desc:"Vocabulary is consistently a notch more charged than the situation calls for.",example:"That's not a delay. That's a betrayal of everyone in this building.",intensity:5,rarity:"signature",pol:{emo:1}},
{id:90037,section:"Vocabulary Traits",category:"Affective & Emotional Intensity",trait:"Every word is the last word",desc:"Speaks as though each sentence might be the final thing they ever say.",example:"Remember this. Remember I said it exactly like this.",intensity:5,rarity:"signature",pol:{emo:1}},
{id:90038,section:"Vocabulary Traits",category:"Affective & Emotional Intensity",trait:"Flattened to nothing",desc:"Word choice registers no affect whatsoever, in any circumstance.",example:"The building collapsed. There were people inside. Anyway.",intensity:5,rarity:"signature",pol:{emo:-1}},

{id:90039,section:"Vocabulary Traits",category:"Conceptual Framework & Loanwords",trait:"One imported word",desc:"Keeps a single term from an old life and uses it out of habit.",example:"It's a — we'd have called it a shakedown. Same thing.",intensity:1,rarity:"common",pol:{}},
{id:90040,section:"Vocabulary Traits",category:"Conceptual Framework & Loanwords",trait:"Half-remembered jargon",desc:"Uses field terms slightly wrong, having picked them up secondhand.",example:"It's a — what's the word — a systemic. A systemic thing.",intensity:1,rarity:"common",pol:{}},
{id:90041,section:"Vocabulary Traits",category:"Conceptual Framework & Loanwords",trait:"Two vocabularies, mixed",desc:"Blends the language of two separate worlds in nearly every sentence.",example:"We'll need a beachhead on the pastoral side of this. Spiritually and logistically.",intensity:4,rarity:"signature",pol:{}},
{id:90042,section:"Vocabulary Traits",category:"Conceptual Framework & Loanwords",trait:"Untranslatable to outsiders",desc:"Speaks so deep inside one specialist frame that non-specialists follow nothing.",example:"Obviously it's a second-order problem. Obviously.",intensity:4,rarity:"signature",pol:{}},
{id:90043,section:"Vocabulary Traits",category:"Conceptual Framework & Loanwords",trait:"The frame has replaced the world",desc:"One professional vocabulary has become the only way they can perceive anything.",example:"My daughter is behind schedule. My marriage is over budget. I'm managing it.",intensity:5,rarity:"signature",pol:{}},
{id:90044,section:"Vocabulary Traits",category:"Conceptual Framework & Loanwords",trait:"Private language",desc:"Has drifted so far into their own coinages that they need translating.",example:"It's gone all thirdways again. You know. Thirdways.",intensity:5,rarity:"signature",pol:{}},

{id:90045,section:"Vocabulary Traits",category:"Directness & Literalness",trait:"Slightly plainer than most",desc:"Trims a little decoration off, without making a point of it.",example:"It didn't work. We'll try again.",intensity:1,rarity:"common",pol:{hon:1}},
{id:90046,section:"Vocabulary Traits",category:"Directness & Literalness",trait:"Skips the softener",desc:"Drops the cushioning phrase most people use, once or twice a conversation.",example:"That won't work.",intensity:1,rarity:"common",pol:{hon:1}},
{id:90047,section:"Vocabulary Traits",category:"Directness & Literalness",trait:"States the worst reading aloud",desc:"Names the least flattering interpretation of events as a matter of course.",example:"You're asking me to lie for you. Let's use the actual word.",intensity:5,rarity:"signature",pol:{hon:1}},
{id:90048,section:"Vocabulary Traits",category:"Directness & Literalness",trait:"Zero social varnish",desc:"Has removed every diplomatic construction from their speech permanently.",example:"That was stupid, you knew it was stupid, and now we're here.",intensity:5,rarity:"signature",pol:{hon:1}},
{id:90049,section:"Vocabulary Traits",category:"Directness & Literalness",trait:"Cannot hear implication at all",desc:"Every hint, hedge, and subtext passes them entirely, always.",example:"'We should talk.' — 'We are talking.'",intensity:5,rarity:"signature",pol:{}},

{id:90050,section:"Vocabulary Traits",category:"Morphological & Structural Lexicon",trait:"One pet construction",desc:"Has a single grammatical habit they repeat without noticing.",example:"It's a bit of a nothing-much, really.",intensity:1,rarity:"common",pol:{}},
{id:90051,section:"Vocabulary Traits",category:"Morphological & Structural Lexicon",trait:"Occasional back-formation",desc:"Shortens a long word into a verb now and then.",example:"He'll enthuse at you for an hour if you let him.",intensity:1,rarity:"common",pol:{}},
{id:90052,section:"Vocabulary Traits",category:"Morphological & Structural Lexicon",trait:"Rebuilds words mid-sentence",desc:"Assembles novel compounds on the fly in most exchanges.",example:"That's proper morning-shaped misery, that is.",intensity:4,rarity:"signature",pol:{}},
{id:90053,section:"Vocabulary Traits",category:"Morphological & Structural Lexicon",trait:"Grammar as personal property",desc:"Has restructured English to their own rules and shows no sign of returning.",example:"I'd un-had it if I could. I can't, so I haven't.",intensity:5,rarity:"signature",pol:{}},
{id:90054,section:"Vocabulary Traits",category:"Morphological & Structural Lexicon",trait:"Nearly every word is invented",desc:"Coinages have crowded out standard vocabulary to the point of obscurity.",example:"Bring the flatterjack and the two smallening ones.",intensity:5,rarity:"signature",pol:{}},

{id:90055,section:"Vocabulary Traits",category:"Phonetic & Auditory Qualities",trait:"Sound overrides sense",desc:"Chooses words for how they land in the ear, even when a clearer one exists.",example:"Not 'ruined'. Wracked. Wracked is the word for it.",intensity:5,rarity:"signature",pol:{}},
{id:90056,section:"Vocabulary Traits",category:"Phonetic & Auditory Qualities",trait:"Speech as continuous music",desc:"Every sentence is shaped for rhythm first, meaning second, always.",example:"(you could set it to a drum; several people have tried)",intensity:5,rarity:"signature",pol:{}},

{id:90057,section:"Vocabulary Traits",category:"Pragmatic Focus & Speech Functions",trait:"Mild softener",desc:"Adds one gentle qualifier to requests, nothing more.",example:"Could you, when you get a moment?",intensity:1,rarity:"common",pol:{}},
{id:90058,section:"Vocabulary Traits",category:"Pragmatic Focus & Speech Functions",trait:"Rarely states a preference",desc:"Frames most wants as observations rather than requests.",example:"There's a draught in here. (does not ask for the door)",intensity:1,rarity:"common",pol:{asrt:-1}},
{id:90059,section:"Vocabulary Traits",category:"Pragmatic Focus & Speech Functions",trait:"Everything is negotiation",desc:"Speech is consistently structured to extract a concession.",example:"I could do that. What would I be getting?",intensity:4,rarity:"signature",pol:{}},
{id:90060,section:"Vocabulary Traits",category:"Pragmatic Focus & Speech Functions",trait:"Language as a tool of record",desc:"Phrases everything so it can be cited back later in their favour.",example:"So we're agreed. In front of everyone. I'll take that.",intensity:4,rarity:"signature",pol:{}},
{id:90061,section:"Vocabulary Traits",category:"Pragmatic Focus & Speech Functions",trait:"Every sentence extracts something",desc:"No utterance is ever purely informational; all of it is working.",example:"Nice coat. Where'd the money come from, then?",intensity:5,rarity:"signature",pol:{}},

{id:90062,section:"Vocabulary Traits",category:"Precision & Specificity Level",trait:"Names the day, not the week",desc:"Slightly more specific than needed about times and places.",example:"Thursday. Not 'a few days ago' — Thursday.",intensity:1,rarity:"common",pol:{}},
{id:90063,section:"Vocabulary Traits",category:"Precision & Specificity Level",trait:"Corrects one detail",desc:"Fixes a single inaccuracy per conversation, then lets the rest go.",example:"Two, actually. Anyway, go on.",intensity:1,rarity:"common",pol:{}},
{id:90064,section:"Vocabulary Traits",category:"Precision & Specificity Level",trait:"Qualifies every claim",desc:"Attaches confidence bounds to most statements as a matter of habit.",example:"Probably. I'd put it at four in five, not certain.",intensity:4,rarity:"signature",pol:{intel:1}},
{id:90065,section:"Vocabulary Traits",category:"Precision & Specificity Level",trait:"Timestamps everything",desc:"Anchors nearly every account to an exact hour.",example:"He left at twenty past six. The lamp was already lit.",intensity:4,rarity:"signature",pol:{intel:1}},
{id:90066,section:"Vocabulary Traits",category:"Precision & Specificity Level",trait:"Cannot tolerate an approximation",desc:"Physically will not continue a conversation containing an unspecified number.",example:"Stop. 'Several'. How many is several. I need the number.",intensity:5,rarity:"signature",pol:{intel:1}},
{id:90067,section:"Vocabulary Traits",category:"Precision & Specificity Level",trait:"Precision as a weapon",desc:"Uses exactitude to trap and humiliate less careful speakers, always.",example:"You said 'about noon'. It was 1:40. Which is it, and why lie about a small thing?",intensity:5,rarity:"signature",pol:{intel:1,warm:-1}},

{id:90068,section:"Vocabulary Traits",category:"Register & Formality Spectrum",trait:"One notch up in company",desc:"Tidies their speech slightly around strangers, then relaxes.",example:"Very good. — Yeah, no, it's fine.",intensity:1,rarity:"common",pol:{man:1}},
{id:90069,section:"Vocabulary Traits",category:"Register & Formality Spectrum",trait:"Formal on paper only",desc:"Writes several registers above how they actually speak.",example:"(says 'yeah'; writes 'I should be most grateful')",intensity:4,rarity:"signature",pol:{man:1}},
{id:90070,section:"Vocabulary Traits",category:"Register & Formality Spectrum",trait:"Deliberately under-speaks",desc:"Uses cruder language than they possess, as a standing choice.",example:"I know the long word. I'm not going to use it with you.",intensity:4,rarity:"signature",pol:{man:-1,rebel:1}},
{id:90071,section:"Vocabulary Traits",category:"Register & Formality Spectrum",trait:"Register never once slips",desc:"Maintains a single formality level in every setting without exception.",example:"(same phrasing to a child, a king, and a corpse)",intensity:5,rarity:"signature",pol:{man:1}},

{id:90072,section:"Vocabulary Traits",category:"Temporal Orientation & Tense Usage",trait:"Occasional backward glance",desc:"Slips into past tense about present things now and then.",example:"That was a good road. Is. Is a good road.",intensity:1,rarity:"common",pol:{}},
{id:90073,section:"Vocabulary Traits",category:"Temporal Orientation & Tense Usage",trait:"Lives in the future tense",desc:"Describes most of the present as though it were already a plan.",example:"By the time we get there it'll have been worth it.",intensity:4,rarity:"signature",pol:{}},
{id:90074,section:"Vocabulary Traits",category:"Temporal Orientation & Tense Usage",trait:"Speaks of themselves in past tense",desc:"Consistently refers to their own life as something already completed.",example:"I was a good hand at it. Not 'am'. Was.",intensity:5,rarity:"signature",pol:{pos:-1}},

/* ---------- Dialogue Grammar Traits ---------- */
{id:90080,section:"Dialogue Grammar Traits",category:"Anchors & Fillers",trait:"Anchor phrase in every breath",desc:"Cannot produce a clause without a stock filler attached, ever.",example:"So basically like I say obviously right so basically—",intensity:5,rarity:"signature",pol:{}},
{id:90081,section:"Dialogue Grammar Traits",category:"Anchors & Fillers",trait:"One phrase, thousands of times",desc:"A single tag has fully colonised their speech; listeners count them.",example:"Do you see. Do you see. Right, but do you see.",intensity:5,rarity:"signature",pol:{}},

{id:90082,section:"Dialogue Grammar Traits",category:"Disfluencies & Flow",trait:"One small hesitation",desc:"A brief catch before difficult words, easily missed.",example:"It was — fine. It was fine.",intensity:1,rarity:"common",pol:{}},
{id:90083,section:"Dialogue Grammar Traits",category:"Disfluencies & Flow",trait:"Occasional lost thread",desc:"Loses the sentence perhaps once a conversation, recovers cleanly.",example:"—sorry. Gone. What was I on?",intensity:1,rarity:"common",pol:{}},
{id:90084,section:"Dialogue Grammar Traits",category:"Disfluencies & Flow",trait:"Speech never completes",desc:"Not one sentence in a conversation reaches its intended end.",example:"I was going to— and then he— which meant— no, hang on—",intensity:5,rarity:"signature",pol:{}},
{id:90085,section:"Dialogue Grammar Traits",category:"Disfluencies & Flow",trait:"Total verbal collapse under weight",desc:"Any emotionally significant topic dismantles their speech entirely.",example:"(three false starts, then nothing at all, for the rest of the evening)",intensity:5,rarity:"signature",pol:{emo:1}},

{id:90086,section:"Dialogue Grammar Traits",category:"Spoken Compression",trait:"Everything is one word",desc:"Has compressed speech to the absolute floor and stayed there.",example:"Out. Now. Gone.",intensity:5,rarity:"signature",pol:{vol:-1}},
{id:90087,section:"Dialogue Grammar Traits",category:"Spoken Compression",trait:"Speaks in fragments others must assemble",desc:"Omits so much that listeners routinely reconstruct meaning wrongly.",example:"Cart. Wrong one. Him. (nobody is sure what happened)",intensity:5,rarity:"signature",pol:{vol:-1}},

{id:90088,section:"Dialogue Grammar Traits",category:"Structural Shifts",trait:"One small aside per story",desc:"Adds a single parenthetical, then returns to the thread.",example:"He left — Tuesday, I think — and that was that.",intensity:1,rarity:"common",pol:{}},
{id:90089,section:"Dialogue Grammar Traits",category:"Structural Shifts",trait:"Never finishes in the shape they started",desc:"Every sentence changes grammatical direction at least once.",example:"The reason I — what you have to understand is — no, start again.",intensity:5,rarity:"signature",pol:{}},

{id:90090,section:"Dialogue Grammar Traits",category:"Turn-Taking Grammar",trait:"Physically cannot yield the floor",desc:"Has never once, in memory, let another person finish a thought.",example:"(interrupts the interruption; then interrupts themselves)",intensity:5,rarity:"signature",pol:{asrt:1,agr:-1}},
{id:90091,section:"Dialogue Grammar Traits",category:"Turn-Taking Grammar",trait:"Waits out any silence",desc:"Will sit in dead air indefinitely rather than take a turn.",example:"(ninety seconds of nothing; they are entirely comfortable)",intensity:5,rarity:"signature",pol:{asrt:-1}},

{id:90092,section:"Dialogue Grammar Traits",category:"Repetition & Echo Patterns",trait:"Echoes the last three words",desc:"Repeats the tail of what was said before answering, most times.",example:"'—by Friday.' — 'By Friday. Right.'",intensity:4,rarity:"signature",pol:{}},
{id:90093,section:"Dialogue Grammar Traits",category:"Repetition & Echo Patterns",trait:"Total echolalia",desc:"Repeats nearly everything said to them before, or instead of, responding.",example:"'Are you all right?' — 'Are you all right. Are you all right.'",intensity:5,rarity:"signature",pol:{}},

/* ---------- Mannerisms ---------- */
{id:90100,section:"Mannerisms",category:"Emotional Affectations",trait:"Feeling arrives whole, instantly, every time",desc:"No lag and no filter between emotion and full physical display, ever.",example:"(is weeping before they've finished reading the first line)",intensity:5,rarity:"signature",pol:{emo:1}},
{id:90101,section:"Mannerisms",category:"Emotional Affectations",trait:"Face has stopped moving entirely",desc:"Facial affect has flatlined permanently, whatever they actually feel.",example:"(told of the death; nothing at all crosses the face)",intensity:5,rarity:"signature",pol:{emo:-1}},

{id:90102,section:"Mannerisms",category:"Environmental Interaction Mannerisms",trait:"Reads the room before speaking",desc:"Scans exits, windows, and faces on entering every space.",example:"(door, window, who's armed, then hello)",intensity:4,rarity:"distinctive",pol:{}},
{id:90103,section:"Mannerisms",category:"Environmental Interaction Mannerisms",trait:"Claims the space immediately",desc:"Rearranges chairs, opens windows, and moves objects in others' rooms.",example:"(moves their host's lamp; does not mention it)",intensity:4,rarity:"distinctive",pol:{asrt:1,man:-1}},
{id:90104,section:"Mannerisms",category:"Environmental Interaction Mannerisms",trait:"Cannot leave a room unchanged",desc:"Physically incapable of being in a space without altering it.",example:"(every object in the room is now two inches from where it was)",intensity:5,rarity:"signature",pol:{}},

{id:90105,section:"Mannerisms",category:"Eye & Facial Expressions",trait:"Unbroken eye contact, always",desc:"Never looks away, for the entire duration of any exchange.",example:"(has not blinked in a length of time people find distressing)",intensity:5,rarity:"signature",pol:{}},
{id:90106,section:"Mannerisms",category:"Eye & Facial Expressions",trait:"Never once meets an eye",desc:"Has not made eye contact with another person in years.",example:"(addresses the space just left of everyone's head)",intensity:5,rarity:"signature",pol:{}},

{id:90107,section:"Mannerisms",category:"Gestural & Kinetic Integration",trait:"Hands never stop, ever",desc:"Continuous, large-scale gesture accompanies every word without pause.",example:"(has knocked over two glasses in one anecdote)",intensity:5,rarity:"signature",pol:{act:1}},
{id:90108,section:"Mannerisms",category:"Gestural & Kinetic Integration",trait:"Total physical stillness",desc:"Speaks and listens without moving anything but the mouth, always.",example:"(has been in exactly this position for forty minutes)",intensity:5,rarity:"signature",pol:{act:-1}},

{id:90109,section:"Mannerisms",category:"Micro-Physical Tics",trait:"One tic, constantly present",desc:"A single small movement running under everything they do.",example:"(thumbnail against thumbnail; all day; every day)",intensity:4,rarity:"signature",pol:{}},
{id:90110,section:"Mannerisms",category:"Micro-Physical Tics",trait:"Tics that stop conversation",desc:"Physical habits are pronounced enough that people lose the thread watching.",example:"(the jaw, the shoulder, the hand — nobody's heard a word)",intensity:5,rarity:"signature",pol:{}},

{id:90111,section:"Mannerisms",category:"Physical Vocalizations & Noises",trait:"Audible in every silence",desc:"Fills all dead air with sound; the room is never actually quiet near them.",example:"(hum, click, sigh, hum, on and on, indefinitely)",intensity:5,rarity:"signature",pol:{}},
{id:90112,section:"Mannerisms",category:"Physical Vocalizations & Noises",trait:"Makes no sound at all",desc:"Moves, breathes, and waits without producing a single audible cue.",example:"(has been standing behind them for some time)",intensity:5,rarity:"signature",pol:{}},

{id:90113,section:"Mannerisms",category:"Postural & Spatial Dynamics",trait:"Occupies the maximum available space",desc:"Expands to fill any room, permanently and without self-consciousness.",example:"(feet on the second chair, arm across the third)",intensity:5,rarity:"distinctive",pol:{asrt:1}},
{id:90114,section:"Mannerisms",category:"Postural & Spatial Dynamics",trait:"Folds into the smallest possible shape",desc:"Compresses their body constantly to take up as little room as they can.",example:"(elbows in, shoulders down, half a chair, always)",intensity:5,rarity:"signature",pol:{ego:-1}},

{id:90115,section:"Mannerisms",category:"Social & Boundary Mannerisms",trait:"Touches while talking",desc:"Habitually makes contact — arm, shoulder, hand — to hold attention.",example:"(hand on the forearm for the whole anecdote)",intensity:4,rarity:"signature",pol:{warm:1}},
{id:90116,section:"Mannerisms",category:"Social & Boundary Mannerisms",trait:"Maintains a fixed distance",desc:"Manages the gap between themselves and others with visible deliberateness.",example:"(steps back exactly as far as they were stepped toward)",intensity:4,rarity:"signature",pol:{warm:-1}},
{id:90117,section:"Mannerisms",category:"Social & Boundary Mannerisms",trait:"No concept of personal space whatsoever",desc:"Stands, leans, and touches without any awareness of the discomfort caused.",example:"(is somehow always four inches closer than anyone wants)",intensity:5,rarity:"signature",pol:{man:-1}},

{id:90118,section:"Mannerisms",category:"Tactile & Prop Handling",trait:"Always holding something",desc:"Reaches for an object within seconds of having empty hands.",example:"(cup, then pen, then the cup again)",intensity:4,rarity:"uncommon",pol:{}},
{id:90119,section:"Mannerisms",category:"Tactile & Prop Handling",trait:"Handles one object obsessively",desc:"Returns to the same carried item dozens of times an hour.",example:"(the coin, out and back into the pocket, and out again)",intensity:4,rarity:"signature",pol:{}},
{id:90120,section:"Mannerisms",category:"Tactile & Prop Handling",trait:"Destroys whatever they're given",desc:"Objects in their hands are systematically dismantled without intent.",example:"(the napkin is confetti; they have not noticed)",intensity:5,rarity:"signature",pol:{}},

{id:90121,section:"Mannerisms",category:"Vocal Modulation Mannerisms",trait:"One volume, no exceptions",desc:"Speaks at exactly the same pitch and volume in every circumstance, always.",example:"(identical delivery for a joke, an order, and a confession)",intensity:5,rarity:"signature",pol:{emo:-1}},
{id:90122,section:"Mannerisms",category:"Vocal Modulation Mannerisms",trait:"Voice swings without warning",desc:"Volume and pitch change violently and unpredictably mid-sentence.",example:"(whispering) I told him — (roaring) I TOLD HIM —(whispering) and he went.",intensity:5,rarity:"signature",pol:{emo:1,disc:-1}},

{id:90123,section:"Mannerisms",category:"Sartorial & Grooming Mannerisms",trait:"Adjusts one item repeatedly",desc:"Straightens the same collar, cuff, or strap throughout a conversation.",example:"(the cuff, again; it was already straight)",intensity:3,rarity:"uncommon",pol:{}},
{id:90124,section:"Mannerisms",category:"Sartorial & Grooming Mannerisms",trait:"Dresses as armour",desc:"Presentation is maintained with visible, effortful discipline at all times.",example:"(three days without sleep; not one thing out of place)",intensity:4,rarity:"signature",pol:{disc:1}},
{id:90125,section:"Mannerisms",category:"Sartorial & Grooming Mannerisms",trait:"Appearance has entirely collapsed",desc:"Has stopped attending to dress and grooming completely, and it shows.",example:"(the same shirt, still; nobody mentions it anymore)",intensity:5,rarity:"signature",pol:{disc:-1,mood:-1}},

/* ---------- Personality Traits ---------- */
{id:90140,section:"Personality Traits",category:"Friendliness — Warm & Approachable",trait:"Remembers one thing about you",desc:"Consistently recalls a single personal detail and asks after it.",example:"Your mother — any better?",intensity:4,rarity:"signature",pol:{warm:1}},
{id:90141,section:"Personality Traits",category:"Friendliness — Warm & Approachable",trait:"Makes room without being asked",desc:"Actively creates space for whoever is on the edge of the group.",example:"(shifts the chair; nods them in)",intensity:4,rarity:"signature",pol:{warm:1}},
{id:90142,section:"Personality Traits",category:"Friendliness — Warm & Approachable",trait:"Warmth costs them nothing",desc:"Gives full, easy friendliness to everyone, endlessly, without depletion.",example:"(the fortieth stranger today gets exactly the same welcome)",intensity:5,rarity:"signature",pol:{warm:1}},
{id:90143,section:"Personality Traits",category:"Friendliness — Cold & Distant",trait:"A beat slow to greet",desc:"Returns friendliness a fraction later than expected, nothing more.",example:"...Hello.",intensity:1,rarity:"common",pol:{warm:-1}},
{id:90144,section:"Personality Traits",category:"Friendliness — Cold & Distant",trait:"Has closed the door permanently",desc:"Has decided against human connection and shows no sign of reopening.",example:"I don't do this. Any of this. Find someone else.",intensity:5,rarity:"signature",pol:{warm:-1}},

{id:90145,section:"Personality Traits",category:"Honesty — Truthful & Transparent",trait:"Won't repeat a rumour",desc:"Quietly declines to pass on anything they can't vouch for.",example:"I've heard it. I haven't confirmed it, so I'll stop there.",intensity:1,rarity:"common",pol:{hon:1}},
{id:90146,section:"Personality Traits",category:"Honesty — Truthful & Transparent",trait:"Volunteers what would go unnoticed",desc:"Reports their own errors before anyone could possibly find them.",example:"Nobody would have known. I'd have known.",intensity:5,rarity:"signature",pol:{hon:1}},
{id:90147,section:"Personality Traits",category:"Honesty — Truthful & Transparent",trait:"Truth ahead of every other value",desc:"Will destroy relationships, plans, and themselves rather than misstate a fact.",example:"It will cost us everything. It's still what happened.",intensity:5,rarity:"signature",pol:{hon:1}},
{id:90148,section:"Personality Traits",category:"Honesty — Deceptive & Evasive",trait:"Rounds things in their favour",desc:"Small facts drift a little toward flattering, nothing more.",example:"Nearly finished. (about half)",intensity:1,rarity:"common",pol:{hon:-1}},
{id:90149,section:"Personality Traits",category:"Honesty — Deceptive & Evasive",trait:"Keeps two versions ready",desc:"Maintains a slightly different account for different listeners.",example:"Depends who's asking, doesn't it.",intensity:2,rarity:"common",pol:{hon:-1}},
{id:90150,section:"Personality Traits",category:"Honesty — Deceptive & Evasive",trait:"Answers a different question",desc:"Replies to a nearby question rather than the one asked.",example:"'Did you take it?' — 'I've been nothing but straight with you.'",intensity:2,rarity:"common",pol:{hon:-1}},
{id:90151,section:"Personality Traits",category:"Honesty — Deceptive & Evasive",trait:"Believes their own account",desc:"Has revised their memory to match the story so completely they aren't lying.",example:"That is what happened. I was there.",intensity:5,rarity:"signature",pol:{hon:-1}},
{id:90152,section:"Personality Traits",category:"Honesty — Deceptive & Evasive",trait:"No true statement left",desc:"Deception has become total; even trivial facts are altered by reflex.",example:"(lies about the weather, to a man standing outside)",intensity:5,rarity:"signature",pol:{hon:-1}},

{id:90153,section:"Personality Traits",category:"Assertiveness — Assertive & Direct",trait:"Says the small no",desc:"Declines minor requests plainly, without apology or explanation.",example:"No, I'd rather not.",intensity:1,rarity:"common",pol:{asrt:1}},
{id:90154,section:"Personality Traits",category:"Assertiveness — Assertive & Direct",trait:"Closes discussions",desc:"Ends debates by stating the decision rather than continuing to argue.",example:"We've talked about it enough. Here's what's happening.",intensity:4,rarity:"signature",pol:{asrt:1}},
{id:90155,section:"Personality Traits",category:"Assertiveness — Assertive & Direct",trait:"Names the problem person",desc:"Says out loud, to the room, who is actually causing the difficulty.",example:"It's not the plan. It's him. We all know it's him.",intensity:4,rarity:"signature",pol:{asrt:1,agr:-1}},
{id:90156,section:"Personality Traits",category:"Assertiveness — Assertive & Direct",trait:"Never once been overruled",desc:"Presses until they win, in every setting, with everyone, permanently.",example:"We'll be here as long as it takes. I've got nowhere to be.",intensity:5,rarity:"signature",pol:{asrt:1}},
{id:90157,section:"Personality Traits",category:"Assertiveness — Passive & Yielding",trait:"Waits to be asked",desc:"Rarely volunteers a view, but gives one if directly invited.",example:"If you're asking — the second one.",intensity:1,rarity:"common",pol:{asrt:-1}},
{id:90158,section:"Personality Traits",category:"Assertiveness — Passive & Yielding",trait:"Defers on everything",desc:"Hands every decision, large or small, to whoever else is present.",example:"You choose. Genuinely, you choose.",intensity:4,rarity:"signature",pol:{asrt:-1}},
{id:90159,section:"Personality Traits",category:"Assertiveness — Passive & Yielding",trait:"Has no stated position on anything",desc:"Cannot be drawn into holding a view, on any subject, ever.",example:"I don't really have a thought about it. Not really. Not one.",intensity:5,rarity:"signature",pol:{asrt:-1}},

{id:90160,section:"Personality Traits",category:"Confidence — Self-Assured",trait:"Takes correction easily",desc:"Absorbs being wrong without any dent to their self-regard.",example:"Ah — you're right. Good. Carry on.",intensity:4,rarity:"signature",pol:{ego:1}},
{id:90161,section:"Personality Traits",category:"Confidence — Self-Assured",trait:"Comfortable being disliked",desc:"Registers hostility clearly and is entirely unmoved by it.",example:"He can't stand me. That's allowed.",intensity:4,rarity:"signature",pol:{ego:1}},
{id:90162,section:"Personality Traits",category:"Confidence — Self-Assured",trait:"Immune to the room",desc:"External opinion has no measurable effect on them under any conditions.",example:"(booed; continues at exactly the same pace)",intensity:5,rarity:"signature",pol:{ego:1}},
{id:90163,section:"Personality Traits",category:"Confidence — Insecure or Egotistical",trait:"Checks once",desc:"Seeks a single small confirmation after doing something.",example:"That was all right, wasn't it?",intensity:1,rarity:"common",pol:{ego:-1}},
{id:90164,section:"Personality Traits",category:"Confidence — Insecure or Egotistical",trait:"Cannot be alone with themselves",desc:"Requires continuous external validation to remain functional at all.",example:"Tell me it was good. No — properly. Say it properly.",intensity:5,rarity:"signature",pol:{ego:-1}},
{id:90165,section:"Personality Traits",category:"Confidence — Insecure or Egotistical",trait:"Grandiosity with no floor beneath it",desc:"Claims total superiority and collapses entirely at the smallest challenge.",example:"I'm the best there's ever been. — Why did you look at me like that.",intensity:5,rarity:"signature",pol:{ego:-1}},

{id:90166,section:"Personality Traits",category:"Agreeableness — Accommodating",trait:"Absorbs the awkward job",desc:"Quietly takes on whatever nobody else wants, most times it comes up.",example:"I'll do it. It's fine, I'll do it.",intensity:4,rarity:"signature",pol:{agr:1}},
{id:90167,section:"Personality Traits",category:"Agreeableness — Accommodating",trait:"Agrees before understanding",desc:"Says yes reflexively to everything, then works out what it meant.",example:"Yes. Absolutely. — What am I agreeing to?",intensity:5,rarity:"signature",pol:{agr:1}},
{id:90168,section:"Personality Traits",category:"Agreeableness — Contrarian & Argumentative",trait:"One small correction",desc:"Offers a single mild disagreement per conversation, then leaves it.",example:"Bit strong, that. Anyway.",intensity:1,rarity:"common",pol:{agr:-1}},
{id:90169,section:"Personality Traits",category:"Agreeableness — Contrarian & Argumentative",trait:"Opposition is the whole personality",desc:"Has no positions of their own, only reversals of everyone else's.",example:"Whatever you're about to say — no.",intensity:5,rarity:"signature",pol:{agr:-1}},

{id:90170,section:"Personality Traits",category:"Manners — Polished & Courteous",trait:"Manages the room's comfort",desc:"Attends to who needs a chair, a drink, or an exit before anyone asks.",example:"(the awkward guest has somehow ended up in the good seat)",intensity:4,rarity:"signature",pol:{man:1}},
{id:90171,section:"Personality Traits",category:"Manners — Polished & Courteous",trait:"Courtesy without a single lapse",desc:"Has never once been rude, under any provocation, to anyone.",example:"(spat at; thanks them for their time)",intensity:5,rarity:"signature",pol:{man:1}},
{id:90172,section:"Personality Traits",category:"Manners — Crude & Ill-Mannered",trait:"Occasionally graceless",desc:"Misses one social beat here and there without malice.",example:"(starts eating before anyone's sat)",intensity:1,rarity:"common",pol:{man:-1}},
{id:90173,section:"Personality Traits",category:"Manners — Crude & Ill-Mannered",trait:"Actively enjoys the offence",desc:"Breaches etiquette deliberately and watches for the reaction, every time.",example:"(waits for the wince; gets it; is delighted)",intensity:5,rarity:"signature",pol:{man:-1,rebel:1}},

{id:90174,section:"Personality Traits",category:"Discipline — Self-Controlled",trait:"Finishes what's in front of them",desc:"Completes the current task before starting another, most days.",example:"This first. Then that.",intensity:1,rarity:"common",pol:{disc:1}},
{id:90175,section:"Personality Traits",category:"Discipline — Self-Controlled",trait:"Keeps the hard promise",desc:"Honours commitments made to themselves as strictly as ones made to others.",example:"I said I'd stop. So I stopped.",intensity:4,rarity:"signature",pol:{disc:1}},
{id:90176,section:"Personality Traits",category:"Discipline — Self-Controlled",trait:"Control has become the identity",desc:"Every impulse is governed, permanently, at visible personal cost.",example:"(wants it badly; will not; has not, in eleven years)",intensity:5,rarity:"signature",pol:{disc:1}},
{id:90177,section:"Personality Traits",category:"Discipline — Impulsive & Undisciplined",trait:"Occasionally derails",desc:"Abandons the plan once in a while, without it becoming a pattern.",example:"Sod it, let's eat first.",intensity:1,rarity:"common",pol:{disc:-1}},
{id:90178,section:"Personality Traits",category:"Discipline — Impulsive & Undisciplined",trait:"Starts more than they finish",desc:"Accumulates half-completed projects faster than they close them.",example:"(four things open; none past the middle)",intensity:4,rarity:"signature",pol:{disc:-1}},
{id:90179,section:"Personality Traits",category:"Discipline — Impulsive & Undisciplined",trait:"Acts before the thought completes",desc:"There is no gap at all between impulse and action, ever.",example:"(has already done it; is now hearing why that was unwise)",intensity:5,rarity:"signature",pol:{disc:-1}},

{id:90180,section:"Personality Traits",category:"Rebelliousness — Defiant",trait:"Asks who decided",desc:"Queries the source of a rule once, then usually complies.",example:"Says who? ...Fine.",intensity:1,rarity:"common",pol:{rebel:1}},
{id:90181,section:"Personality Traits",category:"Rebelliousness — Defiant",trait:"Opposition regardless of cost",desc:"Refuses every instruction from every authority, permanently and totally.",example:"I'd rather lose than be told.",intensity:5,rarity:"signature",pol:{rebel:1}},
{id:90182,section:"Personality Traits",category:"Rebelliousness — Compliant & Conformist",trait:"Prefers the usual way",desc:"Mild preference for how things are normally done.",example:"We've always done it like that, haven't we.",intensity:1,rarity:"common",pol:{rebel:-1}},
{id:90183,section:"Personality Traits",category:"Rebelliousness — Compliant & Conformist",trait:"Checks before deviating",desc:"Seeks approval before any departure from procedure, however small.",example:"Can I? Only it's not how we normally—",intensity:1,rarity:"common",pol:{rebel:-1}},
{id:90184,section:"Personality Traits",category:"Rebelliousness — Compliant & Conformist",trait:"Enforces the rules on others",desc:"Not only follows procedure but polices everyone else's adherence.",example:"That's not the form. Do it on the right form.",intensity:4,rarity:"signature",pol:{rebel:-1}},
{id:90185,section:"Personality Traits",category:"Rebelliousness — Compliant & Conformist",trait:"Obedience without limit",desc:"Would carry out any instruction from legitimate authority, whatever it was.",example:"They wouldn't have ordered it if it weren't right.",intensity:5,rarity:"signature",pol:{rebel:-1}},

{id:90186,section:"Personality Traits",category:"Emotional Capacity — Expressive & Deep",trait:"Admits a small feeling",desc:"Names a minor emotion plainly when it comes up.",example:"That's put me in a mood, actually.",intensity:1,rarity:"common",pol:{emo:1}},
{id:90187,section:"Personality Traits",category:"Emotional Capacity — Expressive & Deep",trait:"Says the difficult thing first",desc:"Leads with the emotional truth rather than working up to it.",example:"I'm frightened. That's why I'm being like this.",intensity:4,rarity:"signature",pol:{emo:1}},
{id:90188,section:"Personality Traits",category:"Emotional Capacity — Expressive & Deep",trait:"Feels other people's lives as their own",desc:"Emotional porousness is total; other people's states arrive undiluted.",example:"I can't be in the room with it. I'm not being dramatic — I can't.",intensity:5,rarity:"signature",pol:{emo:1}},
{id:90189,section:"Personality Traits",category:"Emotional Capacity — Guarded & Shallow",trait:"Changes the subject once",desc:"Steers away from feeling a single time, then engages.",example:"Anyway. — ...All right, go on then.",intensity:1,rarity:"common",pol:{emo:-1}},
{id:90190,section:"Personality Traits",category:"Emotional Capacity — Guarded & Shallow",trait:"Discusses feelings as logistics",desc:"Converts emotional subjects into practical problems by default.",example:"You're upset. What do you need done about it?",intensity:4,rarity:"signature",pol:{emo:-1}},
{id:90191,section:"Personality Traits",category:"Emotional Capacity — Guarded & Shallow",trait:"Has no access to their own interior",desc:"Cannot report what they feel because the information isn't available to them.",example:"I don't know. I genuinely don't know. There's nothing to report.",intensity:5,rarity:"signature",pol:{emo:-1}},

{id:90192,section:"Personality Traits",category:"Intelligence — Sharp & Analytical",trait:"Catches the small inconsistency",desc:"Notices when two statements don't quite line up, occasionally.",example:"You said Tuesday earlier.",intensity:1,rarity:"common",pol:{intel:1}},
{id:90193,section:"Personality Traits",category:"Intelligence — Sharp & Analytical",trait:"Reframes the problem",desc:"Routinely points out that the question being asked is the wrong one.",example:"You're solving the wrong problem. The problem is upstream.",intensity:4,rarity:"signature",pol:{intel:1}},
{id:90194,section:"Personality Traits",category:"Intelligence — Sharp & Analytical",trait:"Several moves ahead of the room",desc:"Has anticipated the conversation's conclusion before it has properly begun.",example:"I know what you're going to ask, and the answer's still no.",intensity:5,rarity:"signature",pol:{intel:1}},
{id:90195,section:"Personality Traits",category:"Intelligence — Instinctive & Unanalytical",trait:"Knows without checking",desc:"Occasionally arrives at the right answer without being able to say why.",example:"That one. Don't ask me.",intensity:1,rarity:"common",pol:{intel:-1}},
{id:90196,section:"Personality Traits",category:"Intelligence — Instinctive & Unanalytical",trait:"Skips to the answer",desc:"Reaches conclusions without any intermediate reasoning, most of the time.",example:"He's lying. No, I can't show you. He's lying.",intensity:4,rarity:"signature",pol:{intel:-1}},
{id:90197,section:"Personality Traits",category:"Intelligence — Instinctive & Unanalytical",trait:"Reasoning is simply unavailable",desc:"Cannot follow or produce a chain of argument of any length, at all.",example:"You've said four things. I got the first one.",intensity:5,rarity:"signature",pol:{intel:-1}},

{id:90198,section:"Personality Traits",category:"Positivity — Optimistic & Upbeat",trait:"Finds the small good",desc:"Notes one redeeming detail in a bad situation.",example:"Well, the rain's stopped.",intensity:1,rarity:"common",pol:{pos:1}},
{id:90199,section:"Personality Traits",category:"Positivity — Optimistic & Upbeat",trait:"Rebuilds morale on purpose",desc:"Actively works to lift a demoralised group, most times it's needed.",example:"Right. Heads up. We've been worse off than this and you know it.",intensity:4,rarity:"signature",pol:{pos:1}},
{id:90200,section:"Personality Traits",category:"Positivity — Optimistic & Upbeat",trait:"Optimism unmoved by evidence",desc:"Maintains total confidence in a good outcome regardless of what happens.",example:"It's going to be fine. — It got worse. — It's going to be fine.",intensity:5,rarity:"signature",pol:{pos:1}},
{id:90201,section:"Personality Traits",category:"Positivity — Pessimistic & Cynical",trait:"Adds a small caveat",desc:"Attaches one note of doubt to good news.",example:"Nice. Let's see if it holds.",intensity:1,rarity:"common",pol:{pos:-1}},
{id:90202,section:"Personality Traits",category:"Positivity — Pessimistic & Cynical",trait:"Cannot register a good outcome",desc:"Reframes every success as a delay before the inevitable failure, always.",example:"So it worked. That just means it'll cost more when it goes.",intensity:5,rarity:"signature",pol:{pos:-1}},

{id:90203,section:"Personality Traits",category:"Activeness — Energetic & Active",trait:"Slightly restless",desc:"A little quicker to stand up than most people.",example:"I'll get it — no, sit down, I'm up.",intensity:1,rarity:"common",pol:{act:1}},
{id:90204,section:"Personality Traits",category:"Activeness — Energetic & Active",trait:"Solves problems by walking",desc:"Physically moves through difficulties rather than sitting with them.",example:"Come on, we'll talk on the way.",intensity:4,rarity:"signature",pol:{act:1}},
{id:90205,section:"Personality Traits",category:"Activeness — Energetic & Active",trait:"Exhausts everyone around them",desc:"Pace is so relentless that companions rotate out to recover.",example:"(third village today; genuinely doesn't understand the complaints)",intensity:4,rarity:"signature",pol:{act:1}},
{id:90206,section:"Personality Traits",category:"Activeness — Energetic & Active",trait:"Motion as a physical requirement",desc:"Becomes visibly unwell if forced to remain still for long.",example:"I can't. I'll walk the perimeter. I have to.",intensity:5,rarity:"signature",pol:{act:1}},
{id:90207,section:"Personality Traits",category:"Activeness — Sedentary & Low-Energy",trait:"Takes the nearer chair",desc:"Makes small, consistent choices that reduce effort.",example:"This one's fine.",intensity:1,rarity:"common",pol:{act:-1}},
{id:90208,section:"Personality Traits",category:"Activeness — Sedentary & Low-Energy",trait:"Conserves for one thing",desc:"Does almost nothing all day in order to do one thing well.",example:"I'm no use before evening. Evening, I'm the best you've got.",intensity:1,rarity:"common",pol:{act:-1}},
{id:90209,section:"Personality Traits",category:"Activeness — Sedentary & Low-Energy",trait:"Negotiates out of physical tasks",desc:"Reliably talks someone else into doing the moving.",example:"You're better at it. Objectively. I've thought about this.",intensity:4,rarity:"signature",pol:{act:-1}},
{id:90210,section:"Personality Traits",category:"Activeness — Sedentary & Low-Energy",trait:"Movement has effectively stopped",desc:"Physical activity has reduced to the minimum required to stay alive.",example:"(the chair, the window, the chair; that's the whole map)",intensity:5,rarity:"signature",pol:{act:-1}},

{id:90211,section:"Personality Traits",category:"Curiosity — Inquisitive & Exploratory",trait:"Asks one follow-up",desc:"Pushes a single question past where most people stop.",example:"And then what happened?",intensity:1,rarity:"common",pol:{}},
{id:90212,section:"Personality Traits",category:"Curiosity — Inquisitive & Exploratory",trait:"Reads the label on everything",desc:"Small, constant investigation of whatever is nearby.",example:"(is already looking at the back of it)",intensity:1,rarity:"common",pol:{}},
{id:90213,section:"Personality Traits",category:"Curiosity — Inquisitive & Exploratory",trait:"Follows the thread past politeness",desc:"Keeps asking after the socially acceptable number of questions has passed.",example:"Sorry — one more. Actually, two more.",intensity:4,rarity:"signature",pol:{}},
{id:90214,section:"Personality Traits",category:"Curiosity — Inquisitive & Exploratory",trait:"Investigates at real cost",desc:"Pursues knowledge past the point where it endangers them, routinely.",example:"I know what's behind it. That's precisely why I'm opening it.",intensity:5,rarity:"signature",pol:{}},
{id:90215,section:"Personality Traits",category:"Curiosity — Incurious & Settled",trait:"Content not to know",desc:"Lets a small unanswered question go without discomfort.",example:"Never found out. Never minded.",intensity:1,rarity:"common",pol:{}},
{id:90216,section:"Personality Traits",category:"Curiosity — Incurious & Settled",trait:"Declines new information",desc:"Actively avoids learning things that would complicate a settled view.",example:"Don't tell me. I'm happy as I am about it.",intensity:4,rarity:"signature",pol:{}},
{id:90217,section:"Personality Traits",category:"Curiosity — Incurious & Settled",trait:"The world was finished years ago",desc:"Has closed all open questions permanently and will not reopen any.",example:"I know what I need to know. I've known it a long time.",intensity:5,rarity:"signature",pol:{}},

/* ---------- Motivation & Wound ---------- */
{id:90230,section:"Motivation & Wound",category:"Core Want (conscious goal)",trait:"A modest, nameable want",desc:"Wants one specific ordinary thing and would say so if asked.",example:"A room with a window. That's genuinely it.",intensity:1,rarity:"common",pol:{}},
{id:90231,section:"Motivation & Wound",category:"Core Want (conscious goal)",trait:"A want that has eaten the person",desc:"Nothing remains of them that isn't in service of this single goal.",example:"There's no me left outside of it. There hasn't been for years.",intensity:5,rarity:"signature",pol:{}},
{id:90232,section:"Motivation & Wound",category:"Core Fear (what they flee)",trait:"A background unease",desc:"A low, manageable worry that shapes small choices only.",example:"I'd rather not, but I would if I had to.",intensity:1,rarity:"common",pol:{}},
{id:90233,section:"Motivation & Wound",category:"Core Fear (what they flee)",trait:"A terror that overrides survival",desc:"Would accept death rather than face this, and knows it.",example:"Kill me here. I'm not going back in.",intensity:5,rarity:"signature",pol:{}},
{id:90234,section:"Motivation & Wound",category:"Core Wound (the old injury)",trait:"An old, mostly closed hurt",desc:"Something that still stings when touched but rarely comes up.",example:"Long time ago. Doesn't come up much.",intensity:1,rarity:"common",pol:{}},
{id:90235,section:"Motivation & Wound",category:"Core Wound (the old injury)",trait:"The wound is the whole architecture",desc:"Every relationship, choice, and fear traces directly back to this one event.",example:"Everything I've done since is that day, still happening.",intensity:5,rarity:"signature",pol:{}},
{id:90236,section:"Motivation & Wound",category:"The Lie They Believe",trait:"A doubt they'd disown",desc:"A quiet false belief they'd deny holding if you named it.",example:"No, I don't think that. ...Mostly I don't think that.",intensity:1,rarity:"common",pol:{}},
{id:90237,section:"Motivation & Wound",category:"The Lie They Believe",trait:"A lie indistinguishable from fact",desc:"This belief is so total it functions as a law of physics for them.",example:"That's not an opinion. That's just how the world is built.",intensity:5,rarity:"signature",pol:{}},

/* ---------- Conflict & Stress Response ---------- */
{id:90250,section:"Conflict & Stress Response",category:"Fight (attack the threat)",trait:"Holds their ground",desc:"Doesn't escalate, but doesn't move either.",example:"I'm still here. Say the rest.",intensity:1,rarity:"common",pol:{asrt:1}},
{id:90251,section:"Conflict & Stress Response",category:"Fight (attack the threat)",trait:"Sharpens up",desc:"Gets a little more pointed under pressure without losing control.",example:"Let's be precise about what you're accusing me of.",intensity:2,rarity:"common",pol:{asrt:1}},
{id:90252,section:"Conflict & Stress Response",category:"Fight (attack the threat)",trait:"Names the disagreement",desc:"Makes the conflict explicit rather than letting it stay under the surface.",example:"We're arguing. Let's at least call it that.",intensity:2,rarity:"common",pol:{asrt:1}},
{id:90253,section:"Conflict & Stress Response",category:"Fight (attack the threat)",trait:"Fights past the point of winning",desc:"Continues attacking long after the threat has been neutralised, every time.",example:"(it's over; they are still going; nobody can stop it)",intensity:5,rarity:"signature",pol:{asrt:1,agr:-1}},
{id:90254,section:"Conflict & Stress Response",category:"Flight (remove yourself)",trait:"Steps outside for a minute",desc:"Takes brief physical distance, then comes back.",example:"Two minutes. I'll be back in two minutes.",intensity:1,rarity:"common",pol:{asrt:-1}},
{id:90255,section:"Conflict & Stress Response",category:"Flight (remove yourself)",trait:"Gone before anyone notices",desc:"Vanishes completely and immediately at the first sign of real conflict, always.",example:"(the chair's warm; nobody saw them get up)",intensity:5,rarity:"signature",pol:{asrt:-1}},
{id:90256,section:"Conflict & Stress Response",category:"Freeze (shut down)",trait:"Needs a beat",desc:"Pauses slightly longer than usual before responding under pressure.",example:"...Sorry. Yes. Go on.",intensity:1,rarity:"common",pol:{ego:-1}},
{id:90257,section:"Conflict & Stress Response",category:"Freeze (shut down)",trait:"Loses hours",desc:"Shuts down so completely that time passes without account.",example:"It was light when we started. I don't know what happened to it.",intensity:5,rarity:"signature",pol:{ego:-1,mood:-1}},
{id:90258,section:"Conflict & Stress Response",category:"Freeze (shut down)",trait:"Body stops before the mind does",desc:"Physically immobilised under pressure while fully aware it's happening.",example:"(knows exactly what to do; cannot make the hand move)",intensity:5,rarity:"signature",pol:{ego:-1,mood:-1}},
{id:90259,section:"Conflict & Stress Response",category:"Fawn (appease the threat)",trait:"Softens the edges",desc:"Slightly rephrases to avoid provoking, without giving ground.",example:"That's fair — I'd just add one thing.",intensity:1,rarity:"common",pol:{agr:1}},
{id:90260,section:"Conflict & Stress Response",category:"Fawn (appease the threat)",trait:"Finds something to agree with",desc:"Locates a point of concession early in any tense exchange.",example:"You're right about the timing, at least.",intensity:2,rarity:"common",pol:{agr:1}},
{id:90261,section:"Conflict & Stress Response",category:"Fawn (appease the threat)",trait:"Manages the other person's mood",desc:"Redirects attention to the aggressor's comfort as tension rises.",example:"You've had a terrible week. Sit down, let me sort it.",intensity:2,rarity:"common",pol:{agr:1,asrt:-1}},
{id:90262,section:"Conflict & Stress Response",category:"Fawn (appease the threat)",trait:"Nothing of them survives the confrontation",desc:"Concedes their position, their account, and their needs entirely, every time.",example:"Whatever you say happened, happened. I'm sorry. I'm sorry.",intensity:5,rarity:"signature",pol:{agr:1,asrt:-1}},

/* ---------- Social Role in a Group ---------- */
{id:90270,section:"Social Role in a Group",category:"Leader",trait:"Speaks up when nobody else will",desc:"Fills a decision vacuum, without wanting the job.",example:"Someone has to say it, so: left.",intensity:1,rarity:"common",pol:{asrt:1}},
{id:90271,section:"Social Role in a Group",category:"Leader",trait:"Carries the group's bad news",desc:"Takes on the job of telling people what they don't want to hear.",example:"I'll tell them. It should come from me.",intensity:4,rarity:"signature",pol:{asrt:1,ego:1}},
{id:90272,section:"Social Role in a Group",category:"Leader",trait:"The group has no shape without them",desc:"Everything organises around this person; in their absence it simply stops.",example:"(three days gone; nothing has been decided by anyone)",intensity:5,rarity:"signature",pol:{asrt:1,ego:1}},
{id:90273,section:"Social Role in a Group",category:"Peacemaker",trait:"Changes the subject kindly",desc:"Redirects away from friction with a light touch, occasionally.",example:"Anyway — has anyone eaten?",intensity:1,rarity:"common",pol:{agr:1}},
{id:90274,section:"Social Role in a Group",category:"Peacemaker",trait:"Refuses to take a side",desc:"Stays deliberately neutral so both parties keep talking to them.",example:"I'm not going to say who's right. I'm going to get you both in a room.",intensity:1,rarity:"common",pol:{agr:1}},
{id:90275,section:"Social Role in a Group",category:"Peacemaker",trait:"Does the repair work afterward",desc:"Follows up privately with each party once the argument is over.",example:"(three separate conversations nobody else knows happened)",intensity:4,rarity:"signature",pol:{agr:1,warm:1}},
{id:90276,section:"Social Role in a Group",category:"Peacemaker",trait:"Would rather lie than let it break",desc:"Will actively misrepresent both sides to keep the group intact, always.",example:"He didn't mean it like that. (He absolutely meant it like that.)",intensity:5,rarity:"signature",pol:{agr:1,warm:1}},
{id:90277,section:"Social Role in a Group",category:"Instigator",trait:"Asks the awkward question",desc:"Raises the thing nobody wants raised, once, then drops it.",example:"Are we not going to mention the money?",intensity:1,rarity:"common",pol:{rebel:1}},
{id:90278,section:"Social Role in a Group",category:"Instigator",trait:"Sets people against each other",desc:"Engineers friction between others and stands back to watch.",example:"He said something similar about you, actually.",intensity:4,rarity:"signature",pol:{rebel:1,agr:-1}},
{id:90279,section:"Social Role in a Group",category:"Instigator",trait:"Forces the decision",desc:"Removes the option of not choosing, repeatedly and deliberately.",example:"I've already told them we're going. So now we're going.",intensity:4,rarity:"signature",pol:{rebel:1}},
{id:90280,section:"Social Role in a Group",category:"Instigator",trait:"Cannot let anything settle",desc:"Destabilises every calm the group achieves, without exception.",example:"(peace lasted four days; they could not bear it)",intensity:5,rarity:"signature",pol:{rebel:1,agr:-1}},
{id:90281,section:"Social Role in a Group",category:"Outsider",trait:"Slightly out of step",desc:"Misses the group's references now and then without minding.",example:"That's clearly a joke I'm not in on. Fine.",intensity:1,rarity:"common",pol:{warm:-1}},
{id:90282,section:"Social Role in a Group",category:"Outsider",trait:"Belongs nowhere at all",desc:"Has no group, in any part of their life, and hasn't for a very long time.",example:"Who would I tell? That's not a sad question. It's a real one.",intensity:5,rarity:"signature",pol:{warm:-1,rebel:1}},
{id:90283,section:"Social Role in a Group",category:"Caretaker",trait:"Notices before they're told",desc:"Spots that someone is struggling ahead of any announcement.",example:"You've not eaten. Sit down.",intensity:4,rarity:"signature",pol:{warm:1}},
{id:90284,section:"Social Role in a Group",category:"Caretaker",trait:"Keeps the group's practical spine",desc:"Handles the unglamorous logistics nobody else remembers exist.",example:"(the water was refilled; nobody knows when)",intensity:4,rarity:"signature",pol:{warm:1,emo:1}},
{id:90285,section:"Social Role in a Group",category:"Caretaker",trait:"Has disappeared into the caring",desc:"Has no remaining self outside of tending to everyone else, at all.",example:"What do I want? That's — no, that's not a real question.",intensity:5,rarity:"signature",pol:{warm:1,emo:1}},
{id:90286,section:"Social Role in a Group",category:"Skeptic",trait:"Raises one eyebrow at the plan",desc:"Registers mild doubt without obstructing anything.",example:"Bold. All right.",intensity:1,rarity:"common",pol:{intel:1}},
{id:90287,section:"Social Role in a Group",category:"Skeptic",trait:"Makes them justify each step",desc:"Requires the reasoning for every stage before agreeing to any of it.",example:"Step two. Why step two. In detail.",intensity:4,rarity:"signature",pol:{intel:1,pos:-1}},
{id:90288,section:"Social Role in a Group",category:"Skeptic",trait:"Nothing is ever sufficiently proven",desc:"No amount of evidence has ever been enough for them to commit, ever.",example:"I've read all of it. I'm still not satisfied.",intensity:5,rarity:"signature",pol:{intel:1,pos:-1}},
{id:90289,section:"Social Role in a Group",category:"Connector",trait:"Knows someone who knows",desc:"Reliably produces a useful name when a problem comes up.",example:"I know a man. I'll write to him tonight.",intensity:3,rarity:"uncommon",pol:{warm:1}},
{id:90290,section:"Social Role in a Group",category:"Connector",trait:"Runs the introductions",desc:"Deliberately builds the group's web of relationships, as an ongoing project.",example:"You two need to meet. I've been meaning to arrange it for a month.",intensity:4,rarity:"signature",pol:{warm:1,act:1}},
{id:90291,section:"Social Role in a Group",category:"Connector",trait:"Everyone flows through them",desc:"No relationship in this group exists that they didn't create or maintain.",example:"(remove them and the cast becomes eight strangers)",intensity:5,rarity:"signature",pol:{warm:1,act:1}},

/* ---------- Values & Moral Line ---------- */
{id:90300,section:"Values & Moral Line",category:"Rigid & Principled",trait:"Holds one line quietly",desc:"Has a single rule they don't break and rarely mentions it.",example:"Not that. Anything else.",intensity:1,rarity:"common",pol:{disc:1,hon:1}},
{id:90301,section:"Values & Moral Line",category:"Rigid & Principled",trait:"Would let the world burn first",desc:"No consequence whatsoever could move them off a stated principle.",example:"Then everyone dies principled. That's still better.",intensity:5,rarity:"signature",pol:{disc:1,hon:1}},
{id:90302,section:"Values & Moral Line",category:"Pragmatic & Flexible",trait:"Bends on the small stuff",desc:"Lets minor rules go when they get in the way.",example:"Nobody's checking. Let's just get on.",intensity:1,rarity:"common",pol:{hon:-1}},
{id:90303,section:"Values & Moral Line",category:"Pragmatic & Flexible",trait:"Prices the principle openly",desc:"Will state plainly what it would take to move them, most times.",example:"For that? No. For twice that, we're talking.",intensity:4,rarity:"signature",pol:{hon:-1,intel:1}},
{id:90304,section:"Values & Moral Line",category:"Pragmatic & Flexible",trait:"There was never a line",desc:"Has no fixed values at all and is entirely untroubled by the fact.",example:"Line? I've never understood what people mean by that.",intensity:5,rarity:"signature",pol:{hon:-1}},
{id:90305,section:"Values & Moral Line",category:"Loyalty-Bound",trait:"Gives the benefit of the doubt",desc:"Extends a little extra trust to their own people.",example:"There'll be a reason. There usually is with him.",intensity:1,rarity:"common",pol:{warm:1,agr:1}},
{id:90306,section:"Values & Moral Line",category:"Loyalty-Bound",trait:"Loyalty survives the evidence",desc:"Stays committed after being shown, conclusively, that they shouldn't.",example:"I've read it. I've read all of it. I'm still not leaving.",intensity:5,rarity:"signature",pol:{warm:1,agr:1}},
{id:90307,section:"Values & Moral Line",category:"Loyalty-Bound",trait:"Would take the sentence for them",desc:"Will accept ruin, imprisonment, or death in another's place without hesitation.",example:"Put my name on it. I'll sign it now.",intensity:5,rarity:"signature",pol:{warm:1,agr:1}},
{id:90308,section:"Values & Moral Line",category:"Self-Interested",trait:"Keeps a slight edge",desc:"Takes marginally the better share when nobody's counting.",example:"(the bigger half; nobody noticed; they did)",intensity:1,rarity:"common",pol:{warm:-1}},
{id:90309,section:"Values & Moral Line",category:"Self-Interested",trait:"Positions for the aftermath",desc:"Arranges every situation so they land well whichever way it goes.",example:"I've been careful about what I've put in writing.",intensity:4,rarity:"signature",pol:{warm:-1,hon:-1}},
{id:90310,section:"Values & Moral Line",category:"Self-Interested",trait:"Sells the group by default",desc:"Their first instinct in any crisis is to trade whoever's nearest for safety.",example:"They're the ones you want. I'll take you to them.",intensity:4,rarity:"signature",pol:{warm:-1,hon:-1}},
{id:90311,section:"Values & Moral Line",category:"Self-Interested",trait:"Other people are not quite real",desc:"Operates as though nobody else's interests exist as facts, at all.",example:"I don't follow. What's the actual problem with that?",intensity:5,rarity:"signature",pol:{warm:-1,hon:-1}},
{id:90312,section:"Values & Moral Line",category:"Idealistic & Visionary",trait:"Believes it could be better",desc:"Holds a mild, unfashionable hope about how things could go.",example:"It doesn't have to be like this, that's all I'm saying.",intensity:1,rarity:"common",pol:{pos:1,hon:1}},
{id:90313,section:"Values & Moral Line",category:"Idealistic & Visionary",trait:"Organises around the vision",desc:"Structures real, practical decisions around a long-range ideal.",example:"We take the slower road because of what it builds.",intensity:4,rarity:"signature",pol:{pos:1,hon:1}},
{id:90314,section:"Values & Moral Line",category:"Idealistic & Visionary",trait:"The ideal outranks every living person",desc:"Would sacrifice anyone, including themselves, for the vision, without pause.",example:"They'll understand. Not now. In fifty years they'll understand.",intensity:5,rarity:"signature",pol:{pos:1,hon:1}},

/* ---------- Attachment & Intimacy Style ---------- */
{id:90330,section:"Attachment & Intimacy Style",category:"Secure",trait:"Says when something's off",desc:"Raises small relational problems early and without drama.",example:"That landed badly. Can we redo it?",intensity:4,rarity:"signature",pol:{ego:1,emo:1}},
{id:90331,section:"Attachment & Intimacy Style",category:"Secure",trait:"Unrattled by distance or silence",desc:"Absence, conflict, and long gaps leave the bond entirely intact for them.",example:"Two years, no letters. Sat down like it was Tuesday.",intensity:5,rarity:"signature",pol:{ego:1,emo:1}},
{id:90332,section:"Attachment & Intimacy Style",category:"Anxious",trait:"Confirms once",desc:"Asks for reassurance a single time, then accepts the answer.",example:"We're fine? — Good. That's all I needed.",intensity:1,rarity:"common",pol:{ego:-1,emo:1}},
{id:90333,section:"Attachment & Intimacy Style",category:"Anxious",trait:"No reassurance ever lands",desc:"Requires constant confirmation and retains none of it, permanently.",example:"You said it an hour ago. I need you to say it again.",intensity:5,rarity:"signature",pol:{ego:-1,emo:1}},
{id:90334,section:"Attachment & Intimacy Style",category:"Avoidant",trait:"Prefers a bit of distance",desc:"Likes closeness in smaller doses than most people.",example:"I'll come Sunday. Not Saturday as well.",intensity:1,rarity:"common",pol:{emo:-1,warm:-1}},
{id:90335,section:"Attachment & Intimacy Style",category:"Avoidant",trait:"Retreats after every good day",desc:"Reliably becomes unreachable in the days following real closeness.",example:"(perfect evening; then nothing for a fortnight)",intensity:4,rarity:"signature",pol:{emo:-1,warm:-1}},
{id:90336,section:"Attachment & Intimacy Style",category:"Avoidant",trait:"Keeps the relationship undeclared",desc:"Refuses to name or define the bond, however long it's lasted.",example:"Why does it need a word attached to it?",intensity:4,rarity:"signature",pol:{emo:-1,warm:-1}},
{id:90337,section:"Attachment & Intimacy Style",category:"Avoidant",trait:"Nobody has ever been let in",desc:"Has maintained complete interior isolation for their entire adult life.",example:"There's nobody. There's never been anybody. That's not a tragedy, it's a design.",intensity:5,rarity:"signature",pol:{emo:-1,warm:-1}},
{id:90338,section:"Attachment & Intimacy Style",category:"Disorganized",trait:"Warmth arrives at odd times",desc:"Affection surfaces unpredictably, without matching the situation.",example:"(cold all week; suddenly, enormously kind, over nothing)",intensity:1,rarity:"common",pol:{mood:-1}},
{id:90339,section:"Attachment & Intimacy Style",category:"Disorganized",trait:"Apologises for the closeness",desc:"Treats their own moments of warmth as errors to be walked back.",example:"Forget I said that. I didn't mean it like it sounded.",intensity:2,rarity:"common",pol:{mood:-1,disc:-1}},
{id:90340,section:"Attachment & Intimacy Style",category:"Disorganized",trait:"Cannot hold a bond in one shape",desc:"The relationship is rebuilt from scratch, differently, nearly every week.",example:"I don't know what we are. I've never once known what we are.",intensity:5,rarity:"signature",pol:{mood:-1,disc:-1}},

/* ---------- Humor Style ---------- */
{id:90350,section:"Humor Style",category:"Dry & Deadpan",trait:"A single flat aside",desc:"Drops one dry remark per conversation and moves on.",example:"Marvellous.",intensity:1,rarity:"common",pol:{intel:1,emo:-1}},
{id:90351,section:"Humor Style",category:"Dry & Deadpan",trait:"Funniest person nobody's sure about",desc:"Consistently sharp, consistently unreadable as to whether it's a joke.",example:"(the room laughs a half-second late, every time)",intensity:4,rarity:"signature",pol:{intel:1,emo:-1}},
{id:90352,section:"Humor Style",category:"Dry & Deadpan",trait:"Has never once signalled a joke",desc:"In a lifetime of wit, has given no tell of any kind, ever.",example:"(nobody has ever seen this person smile at their own line)",intensity:5,rarity:"signature",pol:{intel:1,emo:-1}},
{id:90353,section:"Humor Style",category:"Self-Deprecating",trait:"Small shrug at themselves",desc:"Makes a light joke at their own expense once in a while.",example:"Well, I've done worse.",intensity:1,rarity:"common",pol:{ego:-1}},
{id:90354,section:"Humor Style",category:"Self-Deprecating",trait:"Gets there before you do",desc:"Names their own flaw a beat ahead of anyone else mentioning it.",example:"Yes, the hair. We've all seen it. Onward.",intensity:1,rarity:"common",pol:{ego:-1}},
{id:90355,section:"Humor Style",category:"Self-Deprecating",trait:"Builds intimacy through admitted failure",desc:"Uses their own disasters, routinely, as the main tool for connection.",example:"Let me tell you the worst thing I've ever done. You'll feel better.",intensity:4,rarity:"signature",pol:{ego:-1}},
{id:90356,section:"Humor Style",category:"Self-Deprecating",trait:"The self-mockery has teeth",desc:"Jokes about themselves that are genuinely uncomfortable to be present for.",example:"Nobody would miss me. — No, don't do the face. It's just true, isn't it.",intensity:4,rarity:"signature",pol:{ego:-1}},
{id:90357,section:"Humor Style",category:"Self-Deprecating",trait:"Cannot stop attacking themselves",desc:"Every single utterance contains a diminishment of their own worth.",example:"Sorry — that was stupid — I'm being stupid — sorry.",intensity:5,rarity:"signature",pol:{ego:-1}},
{id:90358,section:"Humor Style",category:"Cruel & Barbed",trait:"One barb, then nothing",desc:"Lands a single sharp line and lets it go.",example:"Ambitious. For you.",intensity:1,rarity:"common",pol:{warm:-1,agr:-1}},
{id:90359,section:"Humor Style",category:"Cruel & Barbed",trait:"Cruelty is the only register left",desc:"No longer capable of humour that isn't aimed at someone, ever.",example:"(has not made a kind joke in living memory)",intensity:5,rarity:"signature",pol:{warm:-1,agr:-1}},
{id:90360,section:"Humor Style",category:"Warm & Playful",trait:"Builds jokes that include the quiet one",desc:"Deliberately constructs humour so the person on the edge gets a line.",example:"—and Ren's about to tell you the best part. Go on, Ren.",intensity:4,rarity:"signature",pol:{warm:1,pos:1}},
{id:90361,section:"Humor Style",category:"Warm & Playful",trait:"Turns any room into a good one",desc:"Warmth and play transform every space they enter, without fail.",example:"(they walked in; forty minutes later nobody wants to leave)",intensity:5,rarity:"signature",pol:{warm:1,pos:1}},
{id:90362,section:"Humor Style",category:"Absurd & Chaotic",trait:"One odd remark",desc:"Says something slightly strange now and then, then carries on normally.",example:"Do doors have a right way round? Anyway.",intensity:1,rarity:"common",pol:{rebel:1}},
{id:90363,section:"Humor Style",category:"Absurd & Chaotic",trait:"Commits well past the joke's life",desc:"Sustains a bit long after the room has stopped finding it funny.",example:"(day three of the accent; two people have asked them to stop)",intensity:4,rarity:"signature",pol:{disc:-1,rebel:1}},
{id:90364,section:"Humor Style",category:"Absurd & Chaotic",trait:"Reality is optional",desc:"Operates in a comic frame so detached that others struggle to engage at all.",example:"I've been elected mayor of this table. First order of business.",intensity:5,rarity:"signature",pol:{disc:-1,rebel:1}},
{id:90365,section:"Humor Style",category:"Absurd & Chaotic",trait:"Nobody can follow where it goes",desc:"Comic logic has become entirely private and untraceable by anyone else.",example:"—which is obviously why the bishop owes me a chicken.",intensity:5,rarity:"signature",pol:{disc:-1,rebel:1}},
{id:90366,section:"Humor Style",category:"Humorless & Absent",trait:"Smiles a beat late",desc:"Registers the joke correctly, just slightly behind everyone else.",example:"(everyone's stopped laughing; they start)",intensity:1,rarity:"common",pol:{pos:-1}},
{id:90367,section:"Humor Style",category:"Humorless & Absent",trait:"Politely waits it out",desc:"Treats humour as an interruption to be endured without comment.",example:"(waits) Right. The gate.",intensity:1,rarity:"common",pol:{pos:-1,disc:1}},
{id:90368,section:"Humor Style",category:"Humorless & Absent",trait:"Actively disapproves of laughter",desc:"Treats levity as a moral failing and says so, most times it occurs.",example:"I don't find this an appropriate moment. I rarely do.",intensity:4,rarity:"signature",pol:{pos:-1,disc:1}},
{id:90369,section:"Humor Style",category:"Humorless & Absent",trait:"Explains why it isn't funny",desc:"Responds to jokes with a careful, unwelcome analysis of their failure.",example:"The premise doesn't hold. That's why nobody laughed.",intensity:4,rarity:"signature",pol:{pos:-1,disc:1}},
{id:90370,section:"Humor Style",category:"Humorless & Absent",trait:"Humour does not exist for them",desc:"Has no register for comedy at all and never has, in any form.",example:"I understand the words. I don't understand the sound people make after.",intensity:5,rarity:"signature",pol:{pos:-1,disc:1}},
{id:90371,section:"Humor Style",category:"Intellectual & Wordplay",trait:"One small pun",desc:"Offers a single mild wordplay and doesn't push it.",example:"Bit of a stretch. Like the rope.",intensity:1,rarity:"common",pol:{intel:1}},
{id:90372,section:"Humor Style",category:"Intellectual & Wordplay",trait:"Enjoys the shape of the sentence",desc:"Takes visible pleasure in constructing a well-made line.",example:"Say that back to me. Wasn't that nicely done?",intensity:1,rarity:"common",pol:{intel:1}},
{id:90373,section:"Humor Style",category:"Intellectual & Wordplay",trait:"Layered reference",desc:"Jokes routinely operate on two or three levels at once.",example:"(the third meaning only lands for one person, an hour later)",intensity:3,rarity:"distinctive",pol:{intel:1}},
{id:90374,section:"Humor Style",category:"Intellectual & Wordplay",trait:"Plays for one listener in the room",desc:"Constructs wit aimed at whoever is clever enough to catch it.",example:"(looks directly at the only person who'll get it)",intensity:4,rarity:"signature",pol:{intel:1}},
{id:90375,section:"Humor Style",category:"Intellectual & Wordplay",trait:"Wit has outrun the audience entirely",desc:"Wordplay is so dense and self-referential that no one follows any of it.",example:"(makes a joke about a joke about a joke; the room is silent)",intensity:5,rarity:"signature",pol:{intel:1}},

/* ---------- Habits & Vices ---------- */
{id:90390,section:"Habits & Vices",category:"Substance & Consumption",trait:"One at the end of the day",desc:"A small fixed indulgence with no wider consequence.",example:"Just the one. Same time every evening.",intensity:1,rarity:"common",pol:{}},
{id:90391,section:"Habits & Vices",category:"Substance & Consumption",trait:"Slightly more than they'd admit",desc:"Consumption is marginally above what they report, and they know it.",example:"Two. — All right, three.",intensity:1,rarity:"common",pol:{disc:-1}},
{id:90392,section:"Habits & Vices",category:"Substance & Consumption",trait:"Structures the day around it",desc:"Schedule quietly bends to guarantee access, most days.",example:"Can't do mornings. Never could.",intensity:1,rarity:"common",pol:{disc:-1}},
{id:90393,section:"Habits & Vices",category:"Substance & Consumption",trait:"It has cost them people",desc:"The habit has already destroyed relationships and continues unchanged.",example:"She left over it. I'm still doing it. Draw your own conclusion.",intensity:5,rarity:"signature",pol:{disc:-1,mood:-1}},
{id:90394,section:"Habits & Vices",category:"Substance & Consumption",trait:"Physically dependent, openly",desc:"Cannot function without it, has stopped pretending otherwise, and continues.",example:"I'm not going to lie to you about it. I'm also not going to stop.",intensity:5,rarity:"signature",pol:{disc:-1,mood:-1}},
{id:90395,section:"Habits & Vices",category:"Compulsion & Ritual",trait:"One small superstition",desc:"Keeps a minor lucky habit without taking it seriously.",example:"Same pocket. Always has been.",intensity:1,rarity:"common",pol:{}},
{id:90396,section:"Habits & Vices",category:"Compulsion & Ritual",trait:"Rechecks once",desc:"Goes back to verify a single thing, then lets it be.",example:"(returns, checks the latch, satisfied)",intensity:1,rarity:"common",pol:{}},
{id:90397,section:"Habits & Vices",category:"Compulsion & Ritual",trait:"Rituals now cost real time",desc:"The routines take long enough that others have started noticing the delay.",example:"Go ahead. I'll catch you up. It takes what it takes.",intensity:4,rarity:"signature",pol:{disc:1,ego:-1}},
{id:90398,section:"Habits & Vices",category:"Compulsion & Ritual",trait:"Cannot be interrupted mid-sequence",desc:"Any break in the ritual forces them to start it over from the beginning.",example:"You spoke. Now I have to do the whole thing again.",intensity:4,rarity:"signature",pol:{disc:1,ego:-1}},
{id:90399,section:"Habits & Vices",category:"Compulsion & Ritual",trait:"The compulsion runs their life",desc:"Every decision is subordinated to the ritual's requirements, without exception.",example:"(missed the funeral; the count wasn't finished)",intensity:5,rarity:"signature",pol:{disc:1,ego:-1}},
{id:90400,section:"Habits & Vices",category:"Compulsion & Ritual",trait:"Ritual as the last handhold",desc:"The routine is openly the only thing keeping them upright, and everyone knows.",example:"If I stop counting I don't know what happens. So I count.",intensity:5,rarity:"signature",pol:{disc:1,ego:-1}},
{id:90401,section:"Habits & Vices",category:"Risk & Escape",trait:"Takes the slightly worse odds",desc:"Chooses the marginally riskier option when it's more interesting.",example:"Let's try it the stupid way first.",intensity:1,rarity:"common",pol:{rebel:1}},
{id:90402,section:"Habits & Vices",category:"Risk & Escape",trait:"Has stopped valuing their own survival",desc:"Takes risks that only make sense if they don't much mind dying.",example:"Somebody has to go first. It genuinely doesn't matter if it's me.",intensity:5,rarity:"signature",pol:{disc:-1,rebel:1}},
{id:90403,section:"Habits & Vices",category:"Restraint & Discipline",trait:"Holds back a little",desc:"Takes slightly less than offered, as a quiet habit.",example:"That's plenty, thanks.",intensity:1,rarity:"common",pol:{disc:1}},
{id:90404,section:"Habits & Vices",category:"Restraint & Discipline",trait:"Denial with visible cost",desc:"Maintains strict restraint while it's obviously difficult for them.",example:"(hand tight on the glass they aren't going to drink)",intensity:4,rarity:"signature",pol:{disc:1}},
{id:90405,section:"Habits & Vices",category:"Restraint & Discipline",trait:"Imposes the discipline on others",desc:"Extends their own restraint into an expectation of everyone nearby.",example:"You don't need that either. I'm saying it because it's true.",intensity:4,rarity:"signature",pol:{disc:1}},
{id:90406,section:"Habits & Vices",category:"Restraint & Discipline",trait:"Denial has become the point",desc:"Restraint is no longer in service of anything; it is the entire practice.",example:"I don't know what I'm saving it for anymore. I just don't take it.",intensity:5,rarity:"signature",pol:{disc:1}},
{id:90407,section:"Habits & Vices",category:"Restraint & Discipline",trait:"Nothing gets through, ever",desc:"Absolute, permanent abstention from every indulgence, across a whole life.",example:"Sixty years. Not once. Not a mouthful.",intensity:5,rarity:"signature",pol:{disc:1}},
{id:90408,section:"Habits & Vices",category:"Avoidance & Procrastination",trait:"Leaves it till the afternoon",desc:"Pushes small tasks back a little, then does them.",example:"After lunch. It'll keep till after lunch.",intensity:1,rarity:"common",pol:{disc:-1}},
{id:90409,section:"Habits & Vices",category:"Avoidance & Procrastination",trait:"Busy with everything except the thing",desc:"Achieves a great deal, none of it the task that actually matters.",example:"(the shed is immaculate; the letter is unwritten)",intensity:4,rarity:"signature",pol:{disc:-1}},
{id:90410,section:"Habits & Vices",category:"Avoidance & Procrastination",trait:"The thing will never be done",desc:"Has avoided one crucial task so long it has become permanent.",example:"Eleven years. I think we can call it a decision now.",intensity:5,rarity:"signature",pol:{disc:-1,mood:-1}},
];


