const TRAITS_SUPPLEMENT_3 = [
/* Personality */
{id:93000,section:"Personality Traits",category:"Friendliness — Warm & Approachable",trait:"Warms to people through their problems",desc:"Connects fastest with someone once there's something concrete to help them with.",example:"So the hinge is broken? Wonderful. Sit down, tell me everything.",intensity:3,rarity:"uncommon",pol:{warm:1}},
{id:93001,section:"Personality Traits",category:"Friendliness — Cold & Distant",trait:"Friendly to categories, cold to individuals",desc:"Speaks warmly about people in general while keeping every actual person at arm's length.",example:"I love this town. (has spoken to nobody in it this month)",intensity:3,rarity:"distinctive",pol:{warm:-1}},
{id:93002,section:"Personality Traits",category:"Honesty — Truthful & Transparent",trait:"Tells the truth slant, but tells it",desc:"Delivers hard truths wrapped in gentler framing without ever changing the substance.",example:"The plan has, let's say, character. Fatal character.",intensity:2,rarity:"common",pol:{hon:1}},
{id:93003,section:"Personality Traits",category:"Honesty — Deceptive & Evasive",trait:"Lies only by omission, scrupulously",desc:"Never states a falsehood but curates which truths get mentioned with great care.",example:"Everything I told you was true. (everything untold was the point)",intensity:3,rarity:"distinctive",pol:{hon:-1}},
{id:93004,section:"Personality Traits",category:"Assertiveness — Assertive & Direct",trait:"Asks the question everyone's avoiding, first",desc:"Opens meetings and conversations with the uncomfortable central question.",example:"Before anything else: can we afford it? No? Then why are we here?",intensity:3,rarity:"uncommon",pol:{asrt:1}},
{id:93005,section:"Personality Traits",category:"Confidence — Self-Assured",trait:"Admits ignorance without a flicker of shame",desc:"Says 'I don't know' as comfortably as any other fact.",example:"No idea. Genuinely none. Who would know?",intensity:3,rarity:"uncommon",pol:{ego:1}},
{id:93006,section:"Personality Traits",category:"Confidence — Insecure or Egotistical",trait:"Collects credentials against a doubt no one raised",desc:"Accumulates certifications and proofs to answer an accusation that only exists internally.",example:"Fourth diploma. Same wall. Same feeling.",intensity:3,rarity:"distinctive",pol:{ego:-1}},
{id:93007,section:"Personality Traits",category:"Discipline — Self-Controlled",trait:"Builds slack into every plan, then never uses it",desc:"Schedules margin for failure and treats not needing it as the actual goal.",example:"We have three spare days. We will not be touching them.",intensity:3,rarity:"uncommon",pol:{disc:1}},
{id:93008,section:"Personality Traits",category:"Rebelliousness — Defiant",trait:"Follows the rule while loudly disputing it",desc:"Complies in action while maintaining continuous verbal objection.",example:"I'm doing it. I want the record to show I think it's idiotic.",intensity:2,rarity:"common",pol:{rebel:1}},
{id:93009,section:"Personality Traits",category:"Emotional Capacity — Expressive & Deep",trait:"Grieves in advance",desc:"Feels losses fully before they happen, sometimes long before.",example:"He's fine. I know he's fine. I've already mourned him twice this week.",intensity:3,rarity:"distinctive",pol:{emo:1}},
{id:93010,section:"Personality Traits",category:"Intelligence — Sharp & Analytical",trait:"Builds the counterargument before the argument",desc:"Works out the strongest objection to their own position before presenting it.",example:"Here's my case. Here's the best case against it. Mine still wins, and here's why.",intensity:3,rarity:"distinctive",pol:{intel:1}},
{id:93011,section:"Personality Traits",category:"Positivity — Optimistic & Upbeat",trait:"Optimistic about people, pessimistic about plans",desc:"Trusts individuals to come through while expecting every scheme to fail.",example:"The plan's doomed. Luckily, we have Marta.",intensity:3,rarity:"distinctive",pol:{pos:1}},
{id:93012,section:"Personality Traits",category:"Activeness — Energetic & Active",trait:"Thinks with their hands",desc:"Cannot work through a problem without physically building, sketching, or arranging something.",example:"Hold on. Let me get the pieces out. I can't see it in my head.",intensity:3,rarity:"uncommon",pol:{act:1}},
{id:93013,section:"Personality Traits",category:"Curiosity — Inquisitive & Exploratory",trait:"Interviews everyone they meet",desc:"Turns every casual encounter into a gentle, genuine interrogation of the other person's life.",example:"A ferryman! How does one become a ferryman? Start at the beginning.",intensity:3,rarity:"uncommon",pol:{}},
/* Motivation & Wound */
{id:93020,section:"Motivation & Wound",category:"Core Want (conscious goal)",trait:"To close the distance to one specific person",desc:"Wants to bridge a long-standing gap with someone still living and reachable.",example:"She's three towns over. Might as well be an ocean. I'm working on the ocean.",intensity:3,rarity:"uncommon",pol:{warm:1,emo:1}},
{id:93021,section:"Motivation & Wound",category:"Core Want (conscious goal)",trait:"To be taken at their word once",desc:"Wants a claim of theirs accepted without demands for proof, just one time.",example:"No documents. No witnesses. Just believe me. Once.",intensity:3,rarity:"distinctive",pol:{hon:1,ego:-1}},
{id:93022,section:"Motivation & Wound",category:"Core Fear (what they flee)",trait:"Fear of inheriting the family ending",desc:"Terrified their life will conclude the same way every relative's did.",example:"They all ended the same way. I keep checking myself for the signs.",intensity:3,rarity:"distinctive",pol:{mood:-1}},
{id:93023,section:"Motivation & Wound",category:"Core Fear (what they flee)",trait:"Fear of being loved for the performance",desc:"Terrified the affection they receive belongs to the persona, not the person.",example:"They love the funny one. I haven't been introduced yet.",intensity:3,rarity:"distinctive",pol:{emo:-1,ego:-1}},
{id:93024,section:"Motivation & Wound",category:"Core Wound (the old injury)",trait:"Was believed too late",desc:"Told the truth, was dismissed, and was vindicated only after the damage was done.",example:"They apologised eventually. The barn had already burned.",intensity:3,rarity:"uncommon",pol:{hon:1}},
{id:93025,section:"Motivation & Wound",category:"Core Wound (the old injury)",trait:"Was someone's second choice, formally",desc:"Was explicitly selected as the fallback — and knows exactly who was first.",example:"I saw the list. I was under the crossed-out name.",intensity:3,rarity:"distinctive",pol:{ego:-1}},
{id:93026,section:"Motivation & Wound",category:"The Lie They Believe",trait:"'If it was easy, it doesn't count'",desc:"Believes only suffering-purchased achievements have any real value.",example:"It went smoothly. So now I'm suspicious of it.",intensity:3,rarity:"uncommon",pol:{disc:1}},
{id:93027,section:"Motivation & Wound",category:"The Lie They Believe",trait:"'I'm the only one not pretending'",desc:"Believes everyone else has secret certainty and only they are improvising.",example:"Everyone else got the manual. I'm the only one winging it.",intensity:3,rarity:"uncommon",pol:{ego:-1}},
/* Stress */
{id:93030,section:"Conflict & Stress Response",category:"Fight (attack the threat)",trait:"Gets extremely calm, which is worse",desc:"Anger presents as a sudden, total, unsettling stillness rather than heat.",example:"(quietly, evenly) Say that one more time.",intensity:4,rarity:"signature",pol:{}},
{id:93031,section:"Conflict & Stress Response",category:"Flight (remove yourself)",trait:"Agrees instantly to end the conversation",desc:"Concedes anything, sincerely or not, purely to make the exit available.",example:"You're right. Completely right. (is already reaching for the door)",intensity:3,rarity:"uncommon",pol:{}},
{id:93032,section:"Conflict & Stress Response",category:"Freeze (shut down)",trait:"Keeps working, stops thinking",desc:"Hands continue the task perfectly while all higher decision-making suspends.",example:"(kept stacking the crates through the entire shouting match)",intensity:3,rarity:"distinctive",pol:{}},
{id:93033,section:"Conflict & Stress Response",category:"Fawn (appease the threat)",trait:"Translates the aggressor to the room",desc:"Reflexively reframes hostile statements into reasonable ones for everyone else.",example:"What he means is — I think what he means is —",intensity:3,rarity:"distinctive",pol:{}},
/* Role */
{id:93040,section:"Social Role in a Group",category:"Leader",trait:"Trains their own replacement openly",desc:"Treats developing whoever comes next as a core, stated duty of the role.",example:"Watch what I do here. One day this is your call.",intensity:3,rarity:"distinctive",pol:{}},
{id:93041,section:"Social Role in a Group",category:"Peacemaker",trait:"Absorbs blame that belongs to nobody",desc:"Claims fault for ambient problems just to give the tension somewhere to land.",example:"That one's on me. (it was on no one. It's handled now.)",intensity:3,rarity:"distinctive",pol:{}},
{id:93042,section:"Social Role in a Group",category:"Outsider",trait:"Watches the group like a play they've seen before",desc:"Observes the group's dynamics with the detached accuracy of a critic, and is usually right.",example:"Act two: someone mentions the money. There it is.",intensity:3,rarity:"distinctive",pol:{}},
{id:93043,section:"Social Role in a Group",category:"Caretaker",trait:"Keeps a supply of exactly what people forget",desc:"Carries the pins, coins, snacks, and spare gloves the group reliably fails to bring.",example:"(produces the exact item, again, from the same bag)",intensity:2,rarity:"common",pol:{}},
{id:93044,section:"Social Role in a Group",category:"Skeptic",trait:"Believes the person, doubts the plan",desc:"Extends full trust to individuals while subjecting every scheme to hostile review.",example:"I'd trust you with my life. This plan, though — walk me through it again.",intensity:3,rarity:"uncommon",pol:{}},
{id:93045,section:"Social Role in a Group",category:"Connector",trait:"Remembers who owes whom, and gently settles it",desc:"Tracks the group's favour economy and quietly nudges debts toward resolution.",example:"You still owe Dara for the cart. Tonight would be a good night.",intensity:3,rarity:"distinctive",pol:{}},
{id:93046,section:"Social Role in a Group",category:"Instigator",trait:"Says the quiet consensus out loud",desc:"Voices what the whole group privately believes but has agreed not to say.",example:"We all think the price is theft. I'm just the one saying it to his face.",intensity:3,rarity:"uncommon",pol:{}},
/* Values */
{id:93050,section:"Values & Moral Line",category:"Rigid & Principled",trait:"Pays debts to people who've forgotten them",desc:"Settles old obligations that the other party stopped tracking years ago.",example:"You lent me a coat in '09. This is about the coat.",intensity:3,rarity:"distinctive",pol:{}},
{id:93051,section:"Values & Moral Line",category:"Pragmatic & Flexible",trait:"Ranks harms and picks the smallest",desc:"Approaches every dilemma as damage arithmetic rather than principle.",example:"Both options are bad. One is four-people bad, one is one-person bad. Next question.",intensity:3,rarity:"uncommon",pol:{}},
{id:93052,section:"Values & Moral Line",category:"Loyalty-Bound",trait:"Keeps showing up after being told not to",desc:"Continues quiet, practical support for someone who has pushed them away.",example:"He told me to stop coming. The wood still gets chopped.",intensity:3,rarity:"distinctive",pol:{}},
{id:93053,section:"Values & Moral Line",category:"Self-Interested",trait:"Helps only where the story will travel",desc:"Chooses which good deeds to do based on which will be retold.",example:"(saves the mayor's dog; walks past the stranger's cat)",intensity:3,rarity:"uncommon",pol:{}},
{id:93054,section:"Values & Moral Line",category:"Idealistic & Visionary",trait:"Plants trees they won't sit under",desc:"Invests real, sustained effort in outcomes they know they won't live to see.",example:"Forty years to grow. I have maybe twenty. Dig anyway.",intensity:3,rarity:"distinctive",pol:{}},
/* Attachment */
{id:93060,section:"Attachment & Intimacy Style",category:"Secure",trait:"Repairs quickly, without keeping score",desc:"Moves from conflict back to closeness fast, holding no ledger of who apologised last.",example:"We fought. It's Tuesday. Both things can just be true.",intensity:3,rarity:"uncommon",pol:{}},
{id:93061,section:"Attachment & Intimacy Style",category:"Anxious",trait:"Memorises exact phrasings for later analysis",desc:"Stores conversations verbatim to re-examine word choices afterward, at length.",example:"You said 'fine'. Earlier you said 'good'. Walk me through the downgrade.",intensity:3,rarity:"distinctive",pol:{}},
{id:93062,section:"Attachment & Intimacy Style",category:"Avoidant",trait:"Shows love through maintenance",desc:"Expresses attachment exclusively via repairs, provisioning, and practical upkeep.",example:"(has never said it; has re-shingled her roof three times)",intensity:3,rarity:"distinctive",pol:{}},
{id:93063,section:"Attachment & Intimacy Style",category:"Disorganized",trait:"Tests the bond by straining it",desc:"Periodically pushes the relationship near breaking specifically to confirm it holds.",example:"I needed to see if you'd stay. You stayed. Ask me again next month.",intensity:4,rarity:"signature",pol:{}},
/* Humor */
{id:93070,section:"Humor Style",category:"Dry & Deadpan",trait:"Compliments delivered as complaints",desc:"Expresses genuine admiration exclusively through the grammar of grievance.",example:"Typical. Absolutely typical that you'd fix it in an hour.",intensity:3,rarity:"distinctive",pol:{}},
{id:93071,section:"Humor Style",category:"Self-Deprecating",trait:"Keeps a highlight reel of their own disasters",desc:"Maintains a polished, ready set of personal failure stories for any occasion.",example:"Which one do you want — the wedding, the boat, or the other boat?",intensity:3,rarity:"uncommon",pol:{}},
{id:93072,section:"Humor Style",category:"Warm & Playful",trait:"Gives everyone a role in the bit",desc:"Builds running jokes with assigned parts so the whole group is in the cast.",example:"You're the sheriff in this one. Dara's the horse. Don't fight it.",intensity:3,rarity:"distinctive",pol:{}},
{id:93073,section:"Humor Style",category:"Absurd & Chaotic",trait:"Treats hypotheticals as pressing business",desc:"Engages ridiculous what-ifs with the urgency of real logistics.",example:"IF the moat were soup, though — no, listen — what KIND of soup?",intensity:3,rarity:"uncommon",pol:{}},
{id:93074,section:"Humor Style",category:"Intellectual & Wordplay",trait:"Puns only in the second language",desc:"Reserves wordplay for a language most of the room doesn't share, entirely for themselves.",example:"(laughs alone at something bilingual; declines to translate)",intensity:3,rarity:"distinctive",pol:{intel:1}},
/* Vices */
{id:93080,section:"Habits & Vices",category:"Substance & Consumption",trait:"Keeps the vice geographically fenced",desc:"Indulges only in one specific place, never elsewhere, as a hard rule.",example:"Only at the coast. That's the deal. The coast, and nowhere else.",intensity:3,rarity:"distinctive",pol:{}},
{id:93081,section:"Habits & Vices",category:"Compulsion & Ritual",trait:"Collects one small useless thing, seriously",desc:"Maintains a growing, ordered collection of some worthless item with real devotion.",example:"That's the '41 bottle-cap. You're joking. That completes the shelf.",intensity:2,rarity:"common",pol:{}},
{id:93082,section:"Habits & Vices",category:"Risk & Escape",trait:"Keeps a running tally of near-misses, proudly",desc:"Counts and recounts close calls as achievements rather than warnings.",example:"That's nine. Nine times it almost got me. I'm going for ten.",intensity:4,rarity:"signature",pol:{rebel:1}},
{id:93083,section:"Habits & Vices",category:"Restraint & Discipline",trait:"Fasts from things nobody would notice",desc:"Practices small private denials — sugar, gossip, the good chair — as quiet exercise.",example:"No, I'm off complaining this month. Ask me in June.",intensity:2,rarity:"common",pol:{disc:1}},
{id:93084,section:"Habits & Vices",category:"Avoidance & Procrastination",trait:"Schedules the avoidance itself",desc:"Formally books time to do the dreaded thing, then reschedules that booking, formally.",example:"Moved 'deal with it' to Thursday. Third Thursday running.",intensity:3,rarity:"distinctive",pol:{disc:-1}},
/* Voice */
{id:93090,section:"Verbosity Traits",category:"High-Volume & Wordy",trait:"Thinks by talking, audibly discards drafts",desc:"Reasons out loud through multiple abandoned versions before landing on the point.",example:"It's like a — no. It's more of a — no. Okay, here's what it actually is.",intensity:3,rarity:"uncommon",pol:{vol:1}},
{id:93091,section:"Verbosity Traits",category:"Minimal & Ultra-Brief",trait:"Saves words like money",desc:"Treats speech as a finite resource being visibly budgeted.",example:"(considers the sentence. Shortens it. Delivers four words.)",intensity:3,rarity:"distinctive",pol:{vol:-1}},
{id:93092,section:"Vocabulary Traits",category:"Abstractness & Sensory Modality",trait:"Describes emotions as locations",desc:"Maps every feeling to a physical place in or around the body.",example:"The dread lives behind the sternum. The guilt is lower.",intensity:3,rarity:"distinctive",pol:{}},
{id:93093,section:"Vocabulary Traits",category:"Precision & Specificity Level",trait:"Refuses to estimate other people's feelings",desc:"Will quantify anything physical but declines all precision about inner states.",example:"The beam is 4.2 metres. How angry is she? I don't do that unit.",intensity:3,rarity:"distinctive",pol:{intel:1}},
{id:93094,section:"Vocabulary Traits",category:"Register & Formality Spectrum",trait:"Reserves formality as a warning sign",desc:"Casual by default; the shift to full names and titles means real trouble.",example:"(all day: 'Sam'. Now, quietly: 'Samuel.') — uh oh.",intensity:3,rarity:"distinctive",pol:{}},
{id:93095,section:"Dialogue Grammar Traits",category:"Turn-Taking Grammar",trait:"Leaves gaps for the shy speaker on purpose",desc:"Deliberately builds silence into conversation shaped for a specific quiet person to fill.",example:"(pauses, looks at the quiet one, waits exactly long enough)",intensity:3,rarity:"distinctive",pol:{warm:1}},
{id:93096,section:"Dialogue Grammar Traits",category:"Spoken Compression",trait:"Answers the next question, skipping the current one",desc:"Compresses exchanges by responding to where the conversation was obviously going.",example:"'Is the road—' 'Flooded. Take the ridge. He's home. Yes you can borrow it.'",intensity:3,rarity:"distinctive",pol:{intel:1}},
{id:93097,section:"Mannerisms",category:"Environmental Interaction Mannerisms",trait:"Feeds whatever animal is present",desc:"Locates and provisions any nearby creature within minutes of arriving anywhere.",example:"(the innkeeper's cat has already been fed. Twice.)",intensity:2,rarity:"common",pol:{warm:1}},
{id:93098,section:"Mannerisms",category:"Micro-Physical Tics",trait:"Mouths other people's words as they speak",desc:"Silently shadows a speaker's sentences a half-beat behind, unaware of doing it.",example:"(lips moving faintly along with the entire announcement)",intensity:3,rarity:"distinctive",pol:{}},
{id:93099,section:"Mannerisms",category:"Vocal Modulation Mannerisms",trait:"Matches the room's accent within the hour",desc:"Unconsciously drifts toward the local speech patterns of wherever they are.",example:"(three days in the port town; already sounds like the docks)",intensity:3,rarity:"uncommon",pol:{}},
];


/* ============================================================================
   APPEARANCE CRAFTER DATA + SUPPLEMENT 4. ids 94000+.
   Appearance uses the same continuous-intensity engine as everything else:
   three dedicated sliders (Stature, Upkeep, Presence) pick pos/neg pools and
   set intensity targets; Movement & Bearing is driven by the existing
   Activeness personality axis; Distinguishing Marks draws at the Presence
   slider's magnitude.
   ========================================================================== */
const TRAITS_APPEARANCE = [
/* Build — Imposing */
{id:94000,section:"Appearance",category:"Build — Imposing",trait:"Takes up slightly more doorway than expected",desc:"Just noticeably broad or tall — people register it and move on.",example:"(a half-step of adjustment when they enter, nothing more)",intensity:1,rarity:"common",pol:{}},
{id:94001,section:"Appearance",category:"Build — Imposing",trait:"Solid in a working way",desc:"Built by labour rather than design; strength that reads as practical.",example:"(the handshake recalibrates your estimate)",intensity:2,rarity:"common",pol:{}},
{id:94002,section:"Appearance",category:"Build — Imposing",trait:"Fills a room without trying",desc:"Height and frame make them the reference point people arrange themselves around.",example:"(the room's geometry quietly reorganises around where they stand)",intensity:3,rarity:"uncommon",pol:{}},
{id:94003,section:"Appearance",category:"Build — Imposing",trait:"Built like the door itself",desc:"Physically massive enough that furniture and doorways become negotiations.",example:"(turns sideways through the frame out of long habit)",intensity:4,rarity:"signature",pol:{}},
{id:94004,section:"Appearance",category:"Build — Imposing",trait:"A silhouette people describe to each other",desc:"So physically imposing that their outline alone is how strangers identify them.",example:"'You'll know him.' — and you do, from two streets away.",intensity:5,rarity:"signature",pol:{}},
/* Build — Slight */
{id:94010,section:"Appearance",category:"Build — Slight",trait:"A little lighter than they look",desc:"Fine-boned in a way that only shows up close.",example:"(the coat does most of the work)",intensity:1,rarity:"common",pol:{}},
{id:94011,section:"Appearance",category:"Build — Slight",trait:"Narrow-shouldered, quick",desc:"Small frame that reads as speed rather than fragility.",example:"(through the crowd gap before it closed)",intensity:2,rarity:"common",pol:{}},
{id:94012,section:"Appearance",category:"Build — Slight",trait:"Easily lost in a crowd of two",desc:"Slight enough to vanish behind almost anyone.",example:"(was standing there the whole time; nobody noticed)",intensity:3,rarity:"uncommon",pol:{}},
{id:94013,section:"Appearance",category:"Build — Slight",trait:"Looks one hard winter from disappearing",desc:"A thinness people quietly worry about.",example:"(two people have independently tried to feed them this week)",intensity:4,rarity:"signature",pol:{}},
{id:94014,section:"Appearance",category:"Build — Slight",trait:"Almost translucent presence",desc:"So physically slight that people startle when they speak, having forgotten the body was there.",example:"(the voice arrives before anyone re-finds the source)",intensity:5,rarity:"signature",pol:{}},
/* Upkeep — Immaculate */
{id:94020,section:"Appearance",category:"Upkeep — Immaculate",trait:"One deliberate touch",desc:"Mostly ordinary, but one detail — the boots, the collar — is always perfect.",example:"(everything's average except the boots. The boots are mirrors.)",intensity:1,rarity:"common",pol:{disc:1}},
{id:94021,section:"Appearance",category:"Upkeep — Immaculate",trait:"Pressed and squared away",desc:"Everything clean, mended, and where it should be, daily.",example:"(the seam sits straight; it always sits straight)",intensity:2,rarity:"common",pol:{disc:1}},
{id:94022,section:"Appearance",category:"Upkeep — Immaculate",trait:"Groomed to a standard nobody set",desc:"Maintains parade-level presentation with no institution requiring it.",example:"Who inspects you? — Nobody. — Then why? — Standards.",intensity:3,rarity:"uncommon",pol:{disc:1}},
{id:94023,section:"Appearance",category:"Upkeep — Immaculate",trait:"Unwrinkled by weather itself",desc:"Emerges from rain, wind, and travel looking freshly dressed, somehow.",example:"(the storm hit everyone. It appears to have skipped them.)",intensity:4,rarity:"signature",pol:{disc:1}},
{id:94024,section:"Appearance",category:"Upkeep — Immaculate",trait:"Presentation as armour, visibly load-bearing",desc:"Perfection maintained with such totality that its slippage would clearly mean collapse.",example:"(the day the cuff was crooked, everyone quietly panicked)",intensity:5,rarity:"signature",pol:{disc:1}},
/* Upkeep — Unkempt */
{id:94030,section:"Appearance",category:"Upkeep — Unkempt",trait:"Perpetually five minutes behind on grooming",desc:"Always slightly rumpled, as if the day started faster than they did.",example:"(one collar point up, one down, permanently)",intensity:1,rarity:"common",pol:{disc:-1}},
{id:94031,section:"Appearance",category:"Upkeep — Unkempt",trait:"Dressed by whatever was nearest",desc:"Clothing selected by proximity rather than intention, daily.",example:"(the shirt was on the chair. So, the shirt.)",intensity:2,rarity:"common",pol:{disc:-1}},
{id:94032,section:"Appearance",category:"Upkeep — Unkempt",trait:"Ink, paint, or grease somewhere, always",desc:"Carries the visible residue of whatever they were last working on.",example:"(you can read their week off their forearms)",intensity:3,rarity:"uncommon",pol:{disc:-1}},
{id:94033,section:"Appearance",category:"Upkeep — Unkempt",trait:"Hair with independent foreign policy",desc:"Grooming has been unilaterally abandoned by at least one region of their person.",example:"(the hair has not been consulted in some time and it shows)",intensity:4,rarity:"signature",pol:{disc:-1}},
{id:94034,section:"Appearance",category:"Upkeep — Unkempt",trait:"Visibly stopped maintaining themselves",desc:"Appearance has collapsed in a way that people notice and worry about.",example:"(the same clothes as Tuesday. And the Tuesday before.)",intensity:5,rarity:"signature",pol:{disc:-1,mood:-1}},
/* Presence — Striking */
{id:94040,section:"Appearance",category:"Presence — Striking",trait:"One feature people remember",desc:"Otherwise ordinary, but a single detail — the eyes, the voice, the scar — stays with people.",example:"'The one with the eyes.' Everyone knows who you mean.",intensity:1,rarity:"common",pol:{}},
{id:94041,section:"Appearance",category:"Presence — Striking",trait:"Photogenic at odd angles",desc:"Interesting-looking rather than pretty; faces like theirs get drawn.",example:"(the sketch artist asked them to sit again, for practice)",intensity:2,rarity:"common",pol:{}},
{id:94042,section:"Appearance",category:"Presence — Striking",trait:"Turns heads without decoration",desc:"Draws a second look in plain clothes and no effort.",example:"(the room does the small double-take, again)",intensity:3,rarity:"uncommon",pol:{}},
{id:94043,section:"Appearance",category:"Presence — Striking",trait:"Beauty that complicates things",desc:"Striking enough that it actively shapes how every interaction goes, wanted or not.",example:"It's not a gift. It's weather. I just live in it.",intensity:4,rarity:"signature",pol:{}},
{id:94044,section:"Appearance",category:"Presence — Striking",trait:"A face that ends conversations",desc:"So arresting that rooms audibly change when they enter; impossible to be anonymous.",example:"(the talking stops. It always stops. They've stopped noticing.)",intensity:5,rarity:"signature",pol:{}},
/* Presence — Unremarkable */
{id:94050,section:"Appearance",category:"Presence — Unremarkable",trait:"Pleasantly forgettable",desc:"A face that's easy to like and hard to describe afterwards.",example:"'What did he look like?' — 'Like... a guy?'",intensity:1,rarity:"common",pol:{}},
{id:94051,section:"Appearance",category:"Presence — Unremarkable",trait:"Looks like someone's cousin",desc:"Reminds everyone vaguely of someone else they know.",example:"You look exactly like — no, it's gone. Someone, though.",intensity:2,rarity:"common",pol:{}},
{id:94052,section:"Appearance",category:"Presence — Unremarkable",trait:"Background-coloured",desc:"Blends into any setting within minutes of arriving.",example:"(three witnesses; three completely different descriptions)",intensity:3,rarity:"uncommon",pol:{}},
{id:94053,section:"Appearance",category:"Presence — Unremarkable",trait:"Professionally invisible",desc:"So unmemorable it functions as a skill — people genuinely can't retain their face.",example:"We've met four times. — We have? — Exactly.",intensity:4,rarity:"signature",pol:{}},
{id:94054,section:"Appearance",category:"Presence — Unremarkable",trait:"A walking absence",desc:"Cameras, witnesses, and memory all slide off them; describing them defeats everyone.",example:"(the sketch artist gave up and drew the chair)",intensity:5,rarity:"signature",pol:{}},
/* Movement & Bearing (driven by Activeness axis) */
{id:94060,section:"Appearance",category:"Movement & Bearing",trait:"Unhurried by policy",desc:"Moves at one deliberate speed regardless of circumstances.",example:"(the building could be on fire; the pace would not change)",intensity:2,rarity:"common",pol:{act:-1}},
{id:94061,section:"Appearance",category:"Movement & Bearing",trait:"Economical, no wasted motion",desc:"Every movement is the minimum required, precisely executed.",example:"(reaches, takes, done — like it was choreographed)",intensity:3,rarity:"uncommon",pol:{disc:1}},
{id:94062,section:"Appearance",category:"Movement & Bearing",trait:"Walks like they're already late",desc:"Perpetual forward lean and pace, even with nowhere to be.",example:"(overtook three people on the way to nowhere in particular)",intensity:3,rarity:"uncommon",pol:{act:1}},
{id:94063,section:"Appearance",category:"Movement & Bearing",trait:"Old injury in the gait",desc:"A slight hitch or favour in how they move — healed, but written in.",example:"(the left side remembers something the right side doesn't)",intensity:3,rarity:"distinctive",pol:{}},
{id:94064,section:"Appearance",category:"Movement & Bearing",trait:"Silent-footed without meaning to be",desc:"Naturally noiseless movement that startles people constantly.",example:"WHERE did you come from. — The door. I used the door.",intensity:3,rarity:"distinctive",pol:{}},
{id:94065,section:"Appearance",category:"Movement & Bearing",trait:"Carries themselves like a former something",desc:"Posture and bearing that clearly belonged to a uniform, a stage, or a title once.",example:"(you can see the parade ground in the shoulders, still)",intensity:3,rarity:"distinctive",pol:{disc:1}},
{id:94066,section:"Appearance",category:"Movement & Bearing",trait:"Constant low-grade motion",desc:"Never fully still — weight shifting, hands moving, always slightly underway.",example:"(technically standing still; visibly idling like an engine)",intensity:4,rarity:"uncommon",pol:{act:1}},
{id:94067,section:"Appearance",category:"Movement & Bearing",trait:"Moves like furniture until suddenly not",desc:"Near-total stillness punctuated by startlingly fast, precise action.",example:"(hadn't moved in an hour; caught the falling jug mid-air)",intensity:4,rarity:"signature",pol:{}},
/* Distinguishing Marks (drawn at Presence magnitude) */
{id:94070,section:"Appearance",category:"Distinguishing Marks",trait:"A small scar with a boring story",desc:"One minor visible mark, origin entirely mundane, story told anyway.",example:"Kitchen door. 2011. I tell it better after a drink.",intensity:1,rarity:"common",pol:{}},
{id:94071,section:"Appearance",category:"Distinguishing Marks",trait:"Hands that don't match the rest",desc:"Hands visibly older, rougher, or finer than everything else about them suggests.",example:"(the hands have done work the face doesn't mention)",intensity:2,rarity:"common",pol:{}},
{id:94072,section:"Appearance",category:"Distinguishing Marks",trait:"Laugh lines or frown lines, committed",desc:"The face has clearly voted, repeatedly, for one expression over decades.",example:"(you can tell which expression won the long war)",intensity:2,rarity:"common",pol:{}},
{id:94073,section:"Appearance",category:"Distinguishing Marks",trait:"An accent that doesn't match the biography",desc:"Speech carries a place they've never admitted living.",example:"You're not from here. — Neither is anyone. — That's not an answer.",intensity:3,rarity:"distinctive",pol:{}},
{id:94074,section:"Appearance",category:"Distinguishing Marks",trait:"Ink they won't explain",desc:"Visible tattooing whose meaning is permanently off the table.",example:"What's it mean? — It means I don't answer that.",intensity:3,rarity:"distinctive",pol:{}},
{id:94075,section:"Appearance",category:"Distinguishing Marks",trait:"Eyes of fractionally different colours",desc:"A subtle mismatch people notice on the second or third meeting.",example:"(everyone eventually does the small squint of confirmation)",intensity:3,rarity:"distinctive",pol:{}},
{id:94076,section:"Appearance",category:"Distinguishing Marks",trait:"A burn, brand, or mark deliberately displayed",desc:"A significant mark that could be covered and pointedly isn't.",example:"(short sleeves, on purpose, every day, including that one)",intensity:4,rarity:"signature",pol:{rebel:1}},
{id:94077,section:"Appearance",category:"Distinguishing Marks",trait:"A mark that makes strangers stare then apologise",desc:"A prominent visible difference that dominates every first impression.",example:"Go on, look. Everyone does. Now — what were you selling?",intensity:5,rarity:"signature",pol:{}},
/* SUPPLEMENT 4 — general breadth */
{id:94100,section:"Personality Traits",category:"Manners — Polished & Courteous",trait:"Thanks people by name, specifically",desc:"Gratitude always arrives personalized and precise, never generic.",example:"Thank you, Ilse — the second lantern especially.",intensity:2,rarity:"common",pol:{man:1}},
{id:94101,section:"Personality Traits",category:"Agreeableness — Accommodating",trait:"Splits every difference by reflex",desc:"Instinctively proposes the midpoint of any two positions, always.",example:"You say five, he says nine. Seven. Done. Next.",intensity:2,rarity:"common",pol:{agr:1}},
{id:94102,section:"Motivation & Wound",category:"Core Want (conscious goal)",trait:"To retire the persona",desc:"Wants to stop being the character everyone expects and see who's underneath.",example:"I've played him for twenty years. I'd like to meet whoever's left.",intensity:4,rarity:"signature",pol:{emo:1,ego:-1}},
{id:94103,section:"Motivation & Wound",category:"Core Fear (what they flee)",trait:"Fear of the favour being called in",desc:"Terrified of the day an old benefactor finally names their price.",example:"He's never asked for anything. That's what worries me.",intensity:3,rarity:"distinctive",pol:{hon:-1}},
{id:94104,section:"Conflict & Stress Response",category:"Freeze (shut down)",trait:"Laughs at the worst possible moment",desc:"Stress escapes as inappropriate, involuntary laughter they can't stop.",example:"(the terrible news lands; the giggle arrives; horror all round)",intensity:3,rarity:"distinctive",pol:{}},
{id:94105,section:"Social Role in a Group",category:"Peacemaker",trait:"Schedules the reconciliation before the fight ends",desc:"Starts arranging the making-up while the argument is still going.",example:"(mid-shouting-match) Dinner Thursday, both of you. It's booked.",intensity:3,rarity:"distinctive",pol:{}},
{id:94106,section:"Values & Moral Line",category:"Loyalty-Bound",trait:"Remembers who was kind first",desc:"Permanent, disproportionate loyalty to whoever helped them before it was safe to.",example:"She hired me when nobody would. She could ask for the shop.",intensity:3,rarity:"uncommon",pol:{}},
{id:94107,section:"Attachment & Intimacy Style",category:"Secure",trait:"Loves people at their actual size",desc:"Neither idealizes nor discounts anyone; affection fits the real person exactly.",example:"He's brilliant and he's lazy. I love the whole inventory.",intensity:3,rarity:"distinctive",pol:{}},
{id:94108,section:"Humor Style",category:"Warm & Playful",trait:"Remembers everyone's best joke and re-serves it",desc:"Quotes people's own funniest moments back to them at perfect times.",example:"As YOU once said — and I quote —",intensity:3,rarity:"distinctive",pol:{}},
{id:94109,section:"Habits & Vices",category:"Compulsion & Ritual",trait:"Says goodbye to rooms",desc:"Quietly acknowledges spaces when leaving them, every time.",example:"(a small nod to the kitchen. The kitchen, presumably, appreciates it.)",intensity:2,rarity:"uncommon",pol:{}},
{id:94110,section:"Vocabulary Traits",category:"Affective & Emotional Intensity",trait:"Swears only in extremity, so it lands like thunder",desc:"Never curses — which makes the one annual exception genuinely alarming.",example:"(the room freezes. In eleven years, nobody's heard that word from her.)",intensity:3,rarity:"distinctive",pol:{}},
{id:94111,section:"Dialogue Grammar Traits",category:"Anchors & Fillers",trait:"Buys time with the listener's last phrase",desc:"Repeats what was just said as a stall while composing the real answer.",example:"'Would I move there.' Would I move there. Well.",intensity:2,rarity:"common",pol:{}},
{id:94112,section:"Mannerisms",category:"Eye & Facial Expressions",trait:"Winks badly and undeterred",desc:"Deploys a technically unsuccessful wink with total confidence, often.",example:"(both eyes. Every time. Unbothered.)",intensity:2,rarity:"common",pol:{pos:1}},
{id:94113,section:"Verbosity Traits",category:"Pacing & Situation-Driven",trait:"Goes quiet exactly when happiest",desc:"Contentment reliably produces silence; chattiness means something's wrong.",example:"(hasn't said a word all evening. Best mood in months.)",intensity:3,rarity:"distinctive",pol:{}},
];


