/* ============================================================================
   MANUAL SECONDARY-TRAIT TAGGING
   ----------------------------------------------------------------------------
   Replaces the earlier regex heuristic. Every personality trait whose NAME is
   built from agent-noun or gerund morphology was pulled (73 candidates) and read
   individually; a second sweep on "always/never/every time" phrasing (65 more)
   was reviewed the same way. The great majority were FALSE POSITIVES — names
   that look symptom-shaped but describe a way of being: "Principled truth-teller",
   "Bold decision-maker", "Adventure-seeking", "Compulsively contrarian",
   "Promise-keeper", "Generous-listener" are dispositions, not tics, and belong
   in core. A sample of short adjectival names was also checked to confirm the
   un-flagged remainder is genuinely core; it was.

   What survived review is below: traits naming ONE narrow recurring behaviour,
   which make poor definitions of a maxed-out axis. This is an explicit auditable
   list rather than a pattern, because the distinction is semantic and a regex
   demonstrably cannot make it — every attempt mislabelled good dispositions.
   ========================================================================== */
const SECONDARY_TRAIT_NAMES = [
  // Confidence — narrow ego/insecurity behaviours
  "Credential-dropping","Credential-flasher","Credential-flashing egotist","Praise-fishing",
  "Compliment-fisher","Comparison-obsessed","Spotlight-seeker","Constant self-monitor",
  "Silence-interpreter-negative","Self-deprecation-fishing insecure","Approval-seeking asker",
  "Quick to apologize for interrupting","Needs the small win acknowledged","Public-praise craving egotist",
  // Assertiveness / agreeableness — discrete interaction habits
  "Ultimatum-giver","Permission-seeking","Position-repeater","Consensus-seeker",
  "Credit-deflector","Conflict-avoiding agreer","Volume-dropping objector","Space-taking speaker",
  "Cost-naming negotiator","Realist-insister","Interruption-avoider",
  // Emotional / social — single recurring acts
  "Feeling-namer","Feeling-deflector","Composure-obsessed","Need-namer","Possibility-namer",
  "Compliment-deflector-grim","Retreat-after-pushback",
  // Manners / friendliness — specific gestures
  "Gentle-teaser","Warmth-extending stranger-greeter","Perfunctory-greeting giver",
  "Insult-as-greeting","Loud-phone-user","Never-says-please","Never-says-please speaker",
  "Never-apologizes","Distance-preferring seater","Silence-preferring colleague",
  "Party-avoider","Disruption-avoider","Neighbor-checker",
  // Discipline / vigilance — trackable habits
  "Receipt-keeper","Grudge-tracker","Rumor-corrector","Fact-checker-combative",
  "Contingency-obsessed","Worst-case-planner","Self-correcting historian",
  "Question-asker","Idea-collector","Credit-taking rude",
];

TRAITS.push(...TRAITS_SUPPLEMENT,...TRAITS_SUPPLEMENT_2,...TRAITS_SUPPLEMENT_3,...TRAITS_APPEARANCE,...TRAITS_APPEARANCE_2,...TRAITS_SUPPLEMENT_5,...TRAITS_SUPPLEMENT_6,...TRAITS_SUPPLEMENT_7,...TRAITS_SUPPLEMENT_8,...TRAITS_NEUTRAL,...TRAITS_MILD,...TRAITS_FILL);

/* ================= MANNERS AXIS SIGNAL PASS =================
   Counting `pol` key frequency across the whole bank, Manners was by far the
   thinnest personality axis: 61 tagged traits, against 1,753 for warm, 1,202 vol,
   1,187 form. Because it's used by roughly 1/29th as many traits as Friendliness,
   every system that reads polarity — the weight matrix, checkConflictsFor,
   axisProfile, the coherence scorer, and the relationship/ensemble notes — had
   almost no Manners signal to reason about, no matter how far the user pushed that
   slider. Those 61 were also almost entirely in Personality Traits (54 of them),
   so the voice layer contributed essentially nothing.

   This tags the voice sections (Verbosity, Vocabulary, Dialogue Grammar,
   Mannerisms), which logically bear on manners — politeness markers, apology,
   deference, yielding or stealing the floor, crude register, contempt.

   Two deliberate constraints:

   1. It is an explicit id-keyed list, not a pattern. A regex pass was written and
      discarded first: it tagged "Utterly blunt — omitting all polite conversational
      buffers" as COURTEOUS (matching "polite" inside its negation), "Unpolished-plain
      — rough, unrefined vocabulary" as refined, and pulled in "Percussive-lexicon"
      and "Domain-borrowed" because "percussive"/"discuss" contain "cuss". This is the
      same conclusion the tier-tagging pass above reached independently: the
      distinction is semantic and a pattern cannot make it.

   2. Manners means COURTESY, not formality of register. Register already has its own
      well-populated axis (`form`, 1,187 traits), so the many "Hyper-formal",
      "Elevated-Latinate", "Legalistic phrasing" entries in the candidate set were
      deliberately NOT tagged — they'd have duplicated `form` and blurred what a
      Manners reading means. Self-interruption ("Chortle-pause", "Interjected-
      correction") is likewise excluded: interrupting yourself is not a manners fact.

   Ids are used rather than names because ids are unique and stable; name-matching is
   exactly the ambiguous path that trait-name collisions made unreliable. */
const MANNERS_COURTEOUS_IDS = [
  // courtly / deferential register that is explicitly about politeness
  157, 160, 200, 332, 366, 1048, 2307, 3296, 3298, 3579,
  // softening, euphemism, tact, diplomatic cushioning
  265, 372, 2216, 2302, 3118, 3294,
  // apology and contrition
  613, 881, 1013, 1165, 3122, 3424, 3626,
  // deference: yielding, offering, or declining the floor; asking permission
  579, 945, 946, 951, 1123, 2325, 2360, 2368, 3417, 3428,
  // physical courtesy and ceremony toward others
  749, 2433, 2447, 3121, 3585,
];
const MANNERS_CRUDE_IDS = [
  // taking or refusing to yield the floor; talking over people
  10, 40, 578, 752, 2001, 2367, 3286, 3416, 3425, 90090, 91812, 91814,
  // crude, vulgar, or profane register
  241, 364, 376, 377, 417, 2306, 3211, 3297,
  // contempt, mockery, and barbed delivery
  603, 604, 617, 2377, 3433,
  // refusal of softening, apology, or social varnish
  97, 2258, 3201, 3261, 90048,
];
let MANNERS_TAG_STATS = null;
(function tagMannersAxis(){
  const byId = new Map(TRAITS.map(t=>[t.id,t]));
  let applied = 0, skipped = 0;
  const apply = (ids, value) => ids.forEach(id=>{
    const t = byId.get(id);
    if (!t) return;
    if (!t.pol) t.pol = {};
    // never overwrite a polarity the trait already declares for itself
    if (t.pol.man !== undefined){ skipped++; return; }
    t.pol.man = value;
    applied++;
  });
  apply(MANNERS_COURTEOUS_IDS, 1);
  apply(MANNERS_CRUDE_IDS, -1);
  MANNERS_TAG_STATS = {listed: MANNERS_COURTEOUS_IDS.length + MANNERS_CRUDE_IDS.length, applied, skipped};
})();
